window.YC_SHL_BANK=[{"id": "shl-1", "module": "shenlun", "category": "归纳概括", "exam": "国考", "year": 2021, "source": "2021年国考市地级第一题（材料改写）", "title": "S县农村电商发展做法概括", "material": ["材料一：近年来，S县把发展农村电商作为促进农民增收的重要抓手。县里成立了电商工作领导小组，由县长任组长，统筹商务、农业、交通、邮政等部门协同推进。先后建成县级电商公共服务中心1个、乡镇服务站18个、村级服务点210个，形成了县乡村三级物流配送体系。", "材料二：S县联合本地职业院校开设电商培训班，累计培训农民主播、网店运营人员3200余人次。针对农产品标准化程度低的问题，县里制定了蜜梨、红薯粉条等12个产品的分级标准和包装规范，注册了区域公用品牌。还与大型电商平台合作开设“S县优品馆”，组织直播带货活动40余场。", "材料三：为解决快递进村“最后一公里”成本高的问题，S县推行“多站合一”模式，将快递收发、便民服务、农产品代购等功能整合到村级服务点，并给予运营补贴。县财政每年安排专项资金500万元，用于物流补贴、人才奖励和品牌推广。"], "question": "根据给定资料，概括S县推动农村电商发展的主要做法。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "成立领导机构，多部门统筹协同推进", "synonyms": ["成立领导小组", "专班推进", "统筹协调", "政府主导", "部门联动", "领导小组", "协同推进", "牵头"], "score": 4}, {"point": "建设县乡村三级服务体系和物流配送网络", "synonyms": ["三级服务体系", "县乡村物流", "服务站点建设", "配送体系", "公共服务中心", "县乡村三级", "物流配送网络", "服务站点"], "score": 3}, {"point": "开展培训，培养电商人才", "synonyms": ["电商培训", "人才培养", "培训农民主播", "职业培训", "人才队伍建设", "开展培训", "培育电商人才", "培训人次"], "score": 3}, {"point": "制定产品标准，打造区域品牌", "synonyms": ["标准化建设", "分级标准", "品牌建设", "注册品牌", "统一包装"], "score": 4}, {"point": "对接电商平台，开展直播带货等营销活动", "synonyms": ["平台合作", "直播带货", "线上营销", "开设优品馆", "拓宽销售渠道"], "score": 3}, {"point": "整合站点功能，财政补贴降低物流成本", "synonyms": ["多站合一", "运营补贴", "专项资金", "降低成本", "资源整合"], "score": 3}], "referenceAnswer": "一是加强组织领导。成立电商工作领导小组，县长牵头，多部门协同推进。二是健全服务体系。建成县乡村三级服务站点和物流配送网络。三是培育电商人才。联合院校开展培训，累计培训3200余人次。四是推进标准化品牌化。制定12个产品分级包装标准，注册区域公用品牌。五是拓宽营销渠道。对接大型电商平台开设优品馆，组织直播带货40余场。六是强化要素保障。推行多站合一整合站点功能，财政每年安排500万元专项资金补贴物流、奖励人才。", "tips": "本题6个采分点全部来自材料，每段材料约对应2个要点。注意把“县长任组长”“多站合一”等口语化表述转成规范表达，分条作答。"}, {"id": "shl-2", "module": "shenlun", "category": "归纳概括", "exam": "省考", "year": 2022, "source": "2022年多省联考第一题（材料改写）", "title": "W社区老旧小区改造成效与问题", "material": ["材料一：W社区建于上世纪90年代，共有12个楼院、2300余户。2021年，社区被列入全市老旧小区改造计划。改造前，社区通过入户走访、居民议事会等方式征集意见，收回有效问卷1800余份，梳理出停车难、管网老化、公共活动空间不足等9类问题。", "材料二：改造中，社区推行“居民点单、社区派单、施工队接单”模式，先改哪、怎么改由居民投票决定。针对停车难，拆除违建腾出空间新增车位86个；针对管网老化，更换供水、排水管道3200米；利用边角地建成小广场2处、健身器材区1处。施工期间聘请8名居民代表担任义务监督员，发现质量问题当场督促整改。", "材料三：改造后，社区建立了“红色物业”党支部，组织居民制定管理公约，推行垃圾定时定点投放。但走访也发现，部分居民仍存在乱停乱放现象，公共设施维护资金不足，一些加装电梯的楼栋因低层住户反对进展缓慢。"], "question": "根据给定资料，概括W社区老旧小区改造的主要做法，并简要说明改造后仍存在的问题。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "改造前广泛征集居民意见，梳理问题清单", "synonyms": ["入户走访", "征集意见", "问卷调研", "居民议事", "问需于民"], "score": 4}, {"point": "推行居民点单派单模式，改造内容由居民投票决定", "synonyms": ["居民点单", "民主决策", "投票决定", "居民参与", "协商共治"], "score": 4}, {"point": "针对停车、管网、活动空间等问题逐项改造", "synonyms": ["新增车位", "更换管道", "建设广场", "完善设施", "拆违建绿"], "score": 4}, {"point": "居民代表担任监督员，全程监督施工质量", "synonyms": ["义务监督员", "居民监督", "督促整改", "质量监督"], "score": 4}, {"point": "问题：部分居民乱停乱放，文明习惯未养成", "synonyms": ["乱停乱放", "行为习惯", "文明意识不足", "管理松懈"], "score": 2}, {"point": "问题：维护资金不足；加装电梯因低层住户反对进展慢", "synonyms": ["资金不足", "经费短缺", "邻里协调难", "意见不统一", "推进缓慢"], "score": 2}], "referenceAnswer": "主要做法：一是改造前入户走访、发放问卷、召开议事会，征集居民意见并梳理9类问题；二是推行“居民点单、社区派单、施工队接单”模式，改造内容由居民投票决定；三是针对停车难、管网老化、活动空间不足逐项改造，新增车位86个、更换管道3200米、建成小广场和健身区；四是聘请居民代表担任义务监督员，督促质量问题当场整改。存在问题：一是部分居民乱停乱放，文明习惯尚未养成；二是公共设施维护资金不足；三是加装电梯因低层住户反对进展缓慢。", "tips": "本题是“做法+问题”两问概括题，前4个采分点答做法、后2个答问题，注意问题部分来自材料三，不要遗漏。"}, {"id": "shl-3", "module": "shenlun", "category": "归纳概括", "exam": "省考", "year": 2023, "source": "2023年多省联考第一题（材料改写）", "title": "L镇非遗保护传承的特点", "material": ["材料一：L镇素有“民间文化艺术之乡”美誉，拥有竹编、皮影、山歌等9项县级以上非遗项目。近年来，该镇建立非遗传承人档案，认定代表性传承人23名，每年发放传承补助。镇文化站开设周末非遗课堂，由传承人轮流授课，累计培训青少年600余人次。", "材料二：L镇探索“非遗+产业”路径，组织竹编艺人成立合作社，开发茶具、灯具等文创产品，年产值超过800万元，带动60余名群众在家门口就业。镇里还把皮影戏、山歌搬进景区常态化演出，节假日期间游客量明显增加。当地中小学把竹编、山歌纳入校本课程，编写了乡土教材。", "材料三：与不少地方“人走艺绝”的困境不同，L镇的非遗项目后继有人。竹编合作社里最年轻的艺人只有24岁，是返乡大学生。皮影戏班子里，80后、90后占了半数。镇党委书记说：“非遗不能锁在柜子里，要让它活在当下、火在生活里。”"], "question": "根据给定资料，概括L镇非遗保护传承工作的特点。（20分）要求：全面、准确、有条理，不超过250字。", "wordLimit": 250, "scorePoints": [{"point": "建立传承人档案，认定传承人并发放补助", "synonyms": ["建档立卡", "认定传承人", "传承补助", "健全档案", "摸清家底"], "score": 4}, {"point": "开设非遗课堂，传承人授课培养青少年", "synonyms": ["非遗课堂", "进校园", "青少年培训", "传承人授课", "周末课堂"], "score": 4}, {"point": "成立合作社开发文创产品，实现产业化发展", "synonyms": ["非遗+产业", "合作社", "文创开发", "产业化", "带动就业"], "score": 4}, {"point": "非遗进景区常态化演出，文旅融合", "synonyms": ["景区演出", "文旅融合", "常态化展演", "吸引游客"], "score": 4}, {"point": "非遗纳入校本课程，编写乡土教材", "synonyms": ["校本课程", "乡土教材", "进校园", "教育传承"], "score": 4}], "referenceAnswer": "一是建档培育强队伍。建立传承人档案，认定23名代表性传承人并发放补助；开设周末非遗课堂，累计培训青少年600余人次。二是产业文旅双赋能。组织竹编艺人成立合作社开发文创产品，年产值超800万元、带动60余人就业；皮影、山歌进景区常态化演出，实现文旅融合。三是教育传承固根基。将竹编、山歌纳入中小学校本课程，编写乡土教材。L镇非遗保护实现从“人走艺绝”到“后继有人”的转变，让非遗活在当下、火在生活里。", "tips": "“特点”类概括题，注意每条先概括再展开。材料三最后一句是点题句，可作为结尾升华，但采分点还是集中在前两段材料。"}, {"id": "shl-4", "module": "shenlun", "category": "综合分析", "exam": "国考", "year": 2022, "source": "2022年国考副省级第二题（材料改写）", "title": "谈谈对“城市文脉”的理解", "material": ["材料一：H市老城区有一条百年商业街，青砖灰瓦、店铺林立。前些年，有人主张整体拆除开发房地产，理由是“老房子不值钱，土地才是钱”。也有专家疾呼：这条街是H市开埠通商的见证，街上的老字号、老建筑承载着几代人的记忆，拆了就再也回不来了。", "材料二：最终H市选择了“修旧如旧、活化利用”的改造路径：修缮老建筑外观，保留历史风貌；内部引入文创工作室、特色书店、传统小吃，让老街既有烟火气又有文化味。改造后，老街年客流量突破千万人次，成为城市新名片。一位老住户说：“逛老街就像翻看家里的老相册，看到的是过去，感受到的是根。”", "材料三：城市文脉是城市的历史记忆和文化基因。习近平总书记指出，城市规划和建设要高度重视历史文化保护，不急功近利，不大拆大建。要突出地方特色，注重人居环境改善，更多采用微改造这种“绣花”功夫。"], "question": "结合给定资料，谈谈你对“城市文脉”的理解。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "城市文脉是城市的历史记忆和文化基因", "synonyms": ["历史记忆", "文化基因", "历史积淀", "文化根脉"], "score": 5}, {"point": "体现在老建筑、老字号等物质载体和居民记忆中", "synonyms": ["老建筑", "老字号", "物质载体", "居民记忆", "乡愁"], "score": 5}, {"point": "保护城市文脉要反对大拆大建，采用微改造“绣花”功夫", "synonyms": ["不大拆大建", "修旧如旧", "微改造", "绣花功夫", "渐进式更新"], "score": 5}, {"point": "活化利用让文脉焕发新生，实现文化经济双赢", "synonyms": ["活化利用", "引入业态", "文化经济双赢", "焕发新生", "可持续发展"], "score": 5}], "referenceAnswer": "城市文脉是城市的历史记忆和文化基因，体现在老建筑、老字号等物质载体和几代居民的情感记忆之中。保护城市文脉，一要转变观念，认识到老建筑承载历史、凝聚乡愁的价值，不能只算经济账、搞大拆大建；二要讲究方法，多用“修旧如旧”的微改造“绣花”功夫，保留历史风貌；三要活化利用，在保护中引入文创、书店等新业态，让老街既有烟火气又有文化味。H市百年商业街的改造证明，文脉保护与经济发展可以双赢，城市文脉得到传承，城市才有根和魂。", "tips": "综合分析题按“是什么—为什么—怎么办”的层次作答。4个采分点分别对应文脉的内涵、载体、保护方法和发展路径，注意结合材料中的案例展开。"}, {"id": "shl-5", "module": "shenlun", "category": "综合分析", "exam": "省考", "year": 2023, "source": "2023年多省联考第二题（材料改写）", "title": "分析“快递进村”遇冷的原因", "material": ["材料一：为打通农村物流“最后一公里”，某县2022年推动快递企业下乡设点，在各村设立快递代收点。然而一年过去，全县87个村级代收点有31个关停，剩下的也大多门可罗雀。快递企业负责人诉苦：一个村每天平均只有30多件包裹，运费加人工成本每天要200多元，长期亏损。", "材料二：村民也有苦衷。李大姐说：“快递只送到村口代收点，不送到家，取一趟要走二里地。网购大件还得自己扛回来，不如让镇上的超市代收，顺路就拿了。”还有村民反映，代收点经常丢件、错领，投诉也没处说。部分村民干脆放弃网购，重回“赶集买东西”的老习惯。", "材料三：邻近的M县做法不同。该县整合邮政、供销社和民营快递资源，实行“多品牌共配”，一辆车捎带多家快递进村，成本降了一半；代收点与村小卖部、村委会合作，村民取件顺路、免费，还能在代收点寄卖土特产。一年下来，M县村级代收点不仅全部存活，业务量还增长了40%。"], "question": "结合给定资料，分析某县“快递进村”遇冷的原因，并简要评价M县做法的启示。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "业务量少，收入覆盖不了运输人工成本，企业亏损", "synonyms": ["件量少", "成本高", "亏损", "入不敷出", "运营成本高", "运输人工成本", "不可持续", "包裹量"], "score": 6}, {"point": "服务不到位：只到村口不入户，取件不便", "synonyms": ["不送上门", "取件远", "不便民", "服务半径大", "不入户", "取件", "到村口", "代收点"], "score": 5}, {"point": "管理不规范：丢件错领，投诉无门，村民信任度低", "synonyms": ["丢件", "错领", "投诉无门", "管理混乱", "信任缺失"], "score": 5}, {"point": "启示：整合资源共配降本，多方合作便民增效", "synonyms": ["多品牌共配", "资源整合", "降本增效", "合作共赢", "因地制宜", "共同配送", "整合", "合作运营", "摊薄成本"], "score": 4}], "referenceAnswer": "遇冷原因：一是经济上不可持续，村均日包裹量仅30余件，运输人工成本每天200多元，企业长期亏损；二是服务不便民，快递只到村口代收点不入户，村民取件往返二里地，网购大件搬运难；三是管理不规范，代收点丢件、错领频发，投诉渠道不畅，村民信任度下降，部分村民放弃网购。M县做法的启示：破解“最后一公里”难题要算大账、聚合力——整合邮政、供销社与民营快递实行共同配送，摊薄成本；依托村小卖部、村委会等既有网点合作运营，让取件顺路免费；叠加土特产寄卖等增值服务，实现企业可持续、村民得实惠的双赢。", "tips": "本题两问：原因3个采分点来自材料一、二，启示1个采分点来自材料三。原因要从企业、村民两个主体分别分析，启示要提炼可推广的普遍做法。"}, {"id": "shl-6", "module": "shenlun", "category": "贯彻执行", "exam": "国考", "year": 2023, "source": "2023年国考市地级第三题（材料改写）", "title": "撰写社区志愿服务活动方案", "material": ["材料一：你是J社区居委会工作人员。近期社区独居老人、双职工家庭儿童“看护难”问题突出，不少居民向社区反映希望组织志愿服务。社区党委决定开展“邻里守望”志愿服务活动，由你起草一份活动方案。", "材料二：社区现有登记志愿者86名，包括退休教师、医护人员、大学生等。社区党群服务中心有两间活动室可用，经费主要靠街道拨款和共建单位赞助。居委会初步设想：服务对象以独居老人、双职工家庭儿童为主；服务内容包括老人探访陪伴、儿童课后托管、代买代办等；时间安排在周末和寒暑假。"], "question": "假如你是J社区居委会工作人员，请根据给定资料，撰写“邻里守望”志愿服务活动方案。（30分）要求：内容全面，条理清晰，结构完整；不超过500字。", "wordLimit": 500, "scorePoints": [{"point": "方案标题规范", "synonyms": ["标题", "关于开展邻里守望志愿服务活动的方案"], "score": 3, "aiOnly": true}, {"point": "明确活动目的：解决独居老人、儿童看护难问题", "synonyms": ["目的", "背景", "看护难", "邻里互助"], "score": 4}, {"point": "明确服务对象：独居老人、双职工家庭儿童", "synonyms": ["服务对象", "独居老人", "儿童", "重点人群"], "score": 4}, {"point": "明确服务内容：探访陪伴、课后托管、代买代办", "synonyms": ["探访", "托管", "代办", "陪伴", "具体服务项目"], "score": 5}, {"point": "明确时间安排：周末和寒暑假", "synonyms": ["时间安排", "周末", "寒暑假", "定期开展"], "score": 4}, {"point": "明确人员组织：志愿者分组、培训、管理", "synonyms": ["志愿者", "分组", "培训", "队伍管理", "招募"], "score": 5}, {"point": "明确保障措施：经费、场地、安全", "synonyms": ["经费", "场地", "安全保障", "物资", "制度保障"], "score": 5}], "referenceAnswer": "J社区“邻里守望”志愿服务活动方案\n一、活动目的：为解决社区独居老人照护缺位、双职工家庭儿童看护难问题，弘扬邻里互助风尚，特开展本次活动。\n二、服务对象：社区独居老人、双职工家庭儿童。\n三、服务内容：1.老人探访陪伴：每周上门探访，提供聊天陪伴、健康提醒、代买代办服务；2.儿童课后托管：周末及寒暑假在社区活动室开设托管班，提供作业辅导和兴趣活动。\n四、时间安排：常态化服务安排在每周末；寒暑假开设全天托管。\n五、人员组织：依托86名登记志愿者，按特长分为探访组、托管组、后勤组；上岗前统一培训，建立服务记录和轮岗制度。\n六、保障措施：使用党群服务中心活动室；经费由街道拨款和共建单位赞助解决；为志愿者购买保险，制定安全预案，确保老人、儿童人身安全。\n七、宣传总结：通过社区公告栏、微信群宣传活动进展，定期评选优秀志愿者，营造守望相助的社区氛围。", "tips": "贯彻执行题重在格式完整、要素齐全。方案类文种要有标题、目的、对象、内容、时间、组织、保障等要素，每个要素对应采分点，注意分条呈现。"}, {"id": "shl-7", "module": "shenlun", "category": "归纳概括", "exam": "国考", "year": 2022, "source": "2022年国考市地级第一题（材料改写）", "title": "H市老旧小区改造的主要做法", "material": ["材料一：H市把老旧小区改造列为民生实事之首。改造前，市住建局组织设计师进社区蹲点调研，逐户发放需求问卷，把加装电梯、增设停车位、适老化改造等群众呼声最高的事项列为必改清单。改造资金采取“居民出一点、政府补一点、社会投一点”的方式筹集，引入两家物业企业参与后续管护。", "材料二：施工期间，每个小区成立由居民代表、社区干部、监理工程师组成的监督小组，对工程质量全程把关，进度每周公示。改造后，社区牵头组建“红色管家”服务队，把快递代收、家电维修、助餐送餐等服务整合进小区服务驿站，居民扫码即可预约。两年来，全市完成改造小区126个，群众满意度达95%。", "材料三：改造中也有插曲。某小区加装电梯时，低层住户担心采光和噪音，一度反对。社区多次组织协商会，最终通过优化井道位置、给予适当补偿达成一致。居民王大爷说：“电梯装好后，楼上楼下都方便，现在大家见面都打招呼，比以前亲热多了。”", "材料四：市住建局负责人介绍，改造不是“一改了之”，后续管护同样重要。市里制定《老旧小区长效管护办法》，明确物业、社区、居民三方责任，把管护效果纳入物业考核，让改造成果长久保持。"], "question": "根据给定资料，概括H市推进老旧小区改造的主要做法。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "改造前问需于民，确定改造清单", "synonyms": ["问需于民", "需求调研", "征集居民意见", "发放问卷"], "score": 4}, {"point": "多元筹措资金，引入社会力量", "synonyms": ["资金多元", "居民出政府补社会投", "引入物业企业", "社会资本参与"], "score": 4}, {"point": "成立监督小组，全程把关质量", "synonyms": ["居民监督", "质量监督", "工程监督小组", "进度公示"], "score": 4}, {"point": "改造后整合服务，建立长效管护", "synonyms": ["长效管护", "整合服务", "服务驿站", "红色管家"], "score": 4}, {"point": "分批推进，成效显著", "synonyms": ["完成改造小区多", "满意度高", "成效明显"], "score": 4}], "referenceAnswer": "一是问需于民。组织设计师蹲点调研，发放问卷，把群众呼声高的事项列为必改清单。二是多元筹资。采取居民出、政府补、社会投方式，引入物业企业参与管护。三是全程监督。成立居民代表、社区干部、监理组成的监督小组，工程质量全程把关，进度每周公示。四是长效管护。组建红色管家服务队，整合快递、维修、助餐等服务进驿站，扫码预约。五是成效显著。两年完成改造126个小区，满意度达95%。", "tips": "命题人提示：本题6个要点对应材料两段，注意“改造前—施工中—改造后”的时间线，把做法概括成动宾结构。"}, {"id": "shl-8", "module": "shenlun", "category": "归纳概括", "exam": "江苏", "year": 2023, "source": "2023年江苏省考A类第一题（材料改写）", "title": "W县优化营商环境的具体举措", "material": ["材料一：W县推出“拿地即开工”审批改革，企业签订土地出让合同当天即可领取施工许可证，项目开工平均提前90天。县政务服务中心设立“办不成事”反映窗口，专门受理企业和群众办事中的疑难问题，全年协调解决堵点事项312件。", "材料二：县里建立企业服务专员制度，为86家重点企业各配备一名服务专员，企业诉求“一口受理、限时办结”。针对中小企业融资难，县财政出资设立风险补偿基金，撬动银行发放贷款18亿元。县纪委监委开通营商环境监督热线，对吃拿卡要、推诿扯皮行为快查快处，全年问责12人。", "材料三：一家科技企业负责人感慨：“以前办施工许可要跑好几个部门，现在网上提交材料，一天就办完了。”县里还推行“跨省通办”，在外地的创业者也能远程办理业务。统计显示，去年全县新登记市场主体同比增长23%，营商环境评价连续三年位居全市前列。", "材料四：不过，也有企业反映，个别政策兑现流程仍显繁琐，申请材料重复提交。县里已启动新一轮流程再造，目标是让政策兑现像网购一样方便。"], "question": "根据给定资料，概括W县优化营商环境的具体举措。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "简化审批流程，加快项目落地", "synonyms": ["拿地即开工", "审批提速", "简化审批", "提前开工"], "score": 5}, {"point": "设立反映窗口，解决办事堵点", "synonyms": ["办不成事窗口", "受理疑难问题", "解决堵点"], "score": 4}, {"point": "配备服务专员，限时办理诉求", "synonyms": ["企业服务专员", "一口受理", "限时办结"], "score": 4}, {"point": "设立补偿基金，缓解融资难题", "synonyms": ["风险补偿基金", "融资支持", "撬动贷款"], "score": 4}, {"point": "强化监督问责，整治不正之风", "synonyms": ["监督热线", "问责", "快查快处", "整治吃拿卡要"], "score": 3}], "referenceAnswer": "一是改革审批。推行拿地即开工，签约当天发证，项目开工平均提前90天。二是疏通堵点。设立办不成事反映窗口，全年协调解决疑难事项312件。三是靠前服务。为重点企业配备服务专员，诉求一口受理、限时办结。四是金融纾困。设立风险补偿基金，撬动银行贷款18亿元，缓解中小企业融资难。五是强化监督。开通营商环境监督热线，对吃拿卡要、推诿扯皮快查快处，全年问责12人。", "tips": "命题人提示：五个要点各对应一个部门举措，注意把具体数据（90天、312件、18亿、12人）作为概括的支撑，不必罗列数据本身。"}, {"id": "shl-9", "module": "shenlun", "category": "归纳概括", "exam": "山东", "year": 2022, "source": "2022年山东省考第一题（材料改写）", "title": "Q村发展乡村产业的经验", "material": ["材料一：Q村曾是省定贫困村。村党支部领办合作社，把全村1200亩土地集中经营，村民以土地入股，年底按股分红。合作社与省农科院合作，引进甘薯新品种，建设脱毒育苗基地，亩均增收2000元。", "材料二：村里注册了商标，对甘薯进行分级包装，进驻电商平台直播销售，去年线上销售额突破800万元。依托育苗基地和加工车间，村里办起甘薯文化节，年接待游客3万人次。产业兴旺吸引了32名年轻人返乡，其中5人进入合作社管理层，村里同步建起电商培训教室，累计培训村民400余人次。", "材料三：合作社理事长算了一笔账：过去村民单打独斗，一亩甘薯收入千把块；现在统一供苗、统一技术、统一销售，亩均增收2000元，入股村民户均分红8000元。村民老李把土地入股后，在合作社务工，一年下来收入比种地翻了一番。", "材料四：县农业农村局把Q村经验在全县推广，已有37个村成立党支部领办合作社。专家点评，Q村的关键在于把党组织的组织优势和合作社的经营优势结合起来，走出了一条强村富民的路子。"], "question": "根据给定资料，归纳Q村发展乡村产业的经验。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "党支部领办合作社，土地规模经营", "synonyms": ["领办合作社", "土地入股", "规模经营", "集中经营"], "score": 5}, {"point": "科技合作，引进良种", "synonyms": ["与科研院所合作", "引进新品种", "科技赋能", "育苗基地"], "score": 4}, {"point": "打造品牌，拓展销售渠道", "synonyms": ["注册商标", "电商直播", "品牌化", "线上销售"], "score": 4}, {"point": "农旅融合，延伸产业链", "synonyms": ["文化节", "农旅融合", "加工车间", "延伸产业链"], "score": 4}, {"point": "吸引人才返乡，培育新农人", "synonyms": ["返乡创业", "人才振兴", "电商培训", "培育村民"], "score": 3}], "referenceAnswer": "一是组织引领。村党支部领办合作社，土地入股集中经营，按股分红。二是科技兴农。与省农科院合作引进甘薯良种，建设脱毒育苗基地，亩均增收2000元。三是品牌营销。注册商标、分级包装，进驻电商直播，线上销售额超800万元。四是三产融合。依托基地办甘薯文化节，年接待游客3万人次。五是人才培育。吸引32名青年返乡，5人进入管理层，培训村民400余人次。", "tips": "命题人提示：经验题按“组织—科技—品牌—融合—人才”五条主线概括，注意每条都要落到具体做法而非空喊口号。"}, {"id": "shl-10", "module": "shenlun", "category": "归纳概括", "exam": "国考", "year": 2021, "source": "2021年国考副省级第二题（材料改写）", "title": "F区“一网通办”改革的成效与做法", "material": ["材料一：F区推行“一网通办”改革，把全区38个部门的1200余项事项接入统一政务平台，实现“一窗受理、并联审批”。企业开办时间从5天压缩到半天，不动产登记实现“交房即交证”。", "材料二：平台上线“免申即享”功能，惠企政策兑现由企业申报改为系统比对、主动推送，去年累计兑现资金2.3亿元，惠及企业4600余家。针对老年人等特殊群体，政务大厅保留人工窗口，并组建帮办代办队伍，提供上门服务。区里还聘请20名企业代表、律师和市民担任“政务服务体验官”，每月体验办事流程并提交改进建议。", "材料三：政务服务改革也带来观念之变。区政务服务中心主任说：“过去是部门各自为政，群众跑断腿；现在是数据跑路，部门协同办。”大厅里还设置了“办不成事”反映窗口，专门兜底解决疑难事项，成立以来受理事项办结率100%。", "材料四：有企业办事人员体验后说：“过去办证照要跑三五趟，现在一次都不用跑，手机上就办好了。”区里计划下一步把更多事项纳入“免申即享”，让改革红利惠及更多市场主体。"], "question": "根据给定资料，概括F区“一网通办”改革的主要做法。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "事项集中接入，一窗受理并联审批", "synonyms": ["一网通办", "统一平台", "一窗受理", "并联审批"], "score": 5}, {"point": "压缩办理时限，提升审批效率", "synonyms": ["压缩时间", "开办提速", "交房即交证", "效率提升"], "score": 4}, {"point": "政策免申即享，主动兑现", "synonyms": ["免申即享", "系统比对", "主动推送", "政策直达"], "score": 4}, {"point": "保留人工窗口，帮办代办上门", "synonyms": ["适老服务", "帮办代办", "上门服务", "人工窗口"], "score": 4}, {"point": "聘请体验官，持续改进服务", "synonyms": ["体验官", "监督建议", "流程改进", "社会监督"], "score": 3}], "referenceAnswer": "一是整合事项。38个部门1200余项事项接入统一平台，一窗受理、并联审批。二是提速增效。企业开办压缩至半天，不动产登记交房即交证。三是政策直达。上线免申即享功能，系统比对主动推送，兑现资金2.3亿元，惠及企业4600余家。四是暖心服务。保留人工窗口，组建帮办代办队伍提供上门服务。五是开门问效。聘请20名体验官每月体验流程、提交改进建议。", "tips": "命题人提示：注意“做法”不等于“成效”，压缩时间、兑现资金是成效，接入平台、上线功能才是做法，概括时以动宾结构表述。"}, {"id": "shl-11", "module": "shenlun", "category": "归纳概括", "exam": "浙江", "year": 2023, "source": "2023年浙江省考第一题（材料改写）", "title": "S镇夜经济发展的特点", "material": ["材料一：入夜后的S镇老街灯火通明。镇里对沿街店铺进行外立面改造，统一设计仿古灯牌，增设300个夜间停车位，两条夜间公交专线延长运营至23点。夜市划定了小吃区、文创区、演艺区，商户持证经营，明码标价。", "材料二：镇里挖掘本地渔家文化，推出沉浸式实景演出《渔灯谣》，每晚两场场场爆满。非遗传承人现场展示鱼灯制作，游客可付费体验。夜市还带动周边村民就业，全镇新增夜间就业岗位1200个，其中低收入农户占两成。商户老陈说：“以前晚上八点就收摊，现在能营业到半夜，一个月多挣四千块。”", "材料三：夜经济的红火离不开精细管理。镇里成立夜市管理办公室，配备专职保洁和安保，垃圾定点清运，噪音实时监测。商户统一亮证经营，游客扫码即可投诉。镇党委书记说：“夜经济不是夜市摊，要有文化味、人情味，还要有秩序。”", "材料四：数据显示，S镇夜间消费额占全天比重由三成提高到五成，周边民宿节假日一房难求。文旅部门将S镇列为夜间文旅消费集聚区培育对象。"], "question": "根据给定资料，概括S镇发展夜经济的特点。（20分）要求：全面、准确、有条理，不超过250字。", "wordLimit": 250, "scorePoints": [{"point": "完善设施配套，优化夜间环境", "synonyms": ["外立面改造", "增设停车位", "公交延长", "设施配套"], "score": 5}, {"point": "规范市场秩序，分区持证经营", "synonyms": ["划定区域", "持证经营", "明码标价", "规范经营"], "score": 5}, {"point": "挖掘本土文化，打造特色项目", "synonyms": ["实景演出", "渔家文化", "沉浸式", "非遗展示"], "score": 5}, {"point": "带动就业增收，惠及低收入群体", "synonyms": ["新增岗位", "带动就业", "低收入农户受益", "增收"], "score": 5}], "referenceAnswer": "一是设施先行。改造店铺外立面，统一灯牌，增设夜间停车位，公交延长运营至23点。二是规范有序。夜市分区经营，商户持证、明码标价。三是文化铸魂。挖掘渔家文化，推出沉浸式实景演出，非遗鱼灯可体验。四是富民惠民。新增夜间就业岗位1200个，低收入农户占两成，商户营业时间延长、收入明显增加。", "tips": "命题人提示：特点题要答出“人无我有”的个性，本题四个特点分别对应设施、秩序、文化、富民，注意每条概括不超过一行。"}, {"id": "shl-12", "module": "shenlun", "category": "归纳概括", "exam": "国考", "year": 2023, "source": "2023年国考市地级第一题（材料改写）", "title": "L县推行河长制的做法", "material": ["材料一：L县建立县乡村三级河长体系，全县97条河流每条都有河长公示牌，公示河长姓名、职责和监督电话。河长使用巡河APP打卡巡河，发现问题拍照上传，系统自动派单给责任部门，限期整改销号。", "材料二：县里聘请62名沿河村民担任民间护河员，发现偷排污水、非法捕捞等行为可即时举报，查实后给予奖励。县财政每年安排专项资金用于河道清淤和生态修复，两年来清理河道垃圾1.2万吨，修复生态岸线15公里。县里还把河长制考核纳入乡镇年度综合考核，考核结果与干部评优挂钩。", "材料三：河长制还带动了全民治河。沿河村镇把护河要求写进村规民约，学校开展“小河长”实践活动，志愿者定期巡河捡拾垃圾。一位民间护河员说：“以前河里漂着垃圾没人管，现在大家抢着管。”", "材料四：县水利局负责人表示，河长制不是“冠名制”，关键在落实。县里每季度通报河长履职情况，对履职不力的约谈提醒，连续两次排名靠后的启动问责。", "县里还开展“最美河长”“最美护河员”评选，营造比学赶超氛围。"], "question": "根据给定资料，概括L县推行河长制的主要做法。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "建立三级河长体系，公示职责", "synonyms": ["三级河长", "公示牌", "责任到人", "河长体系"], "score": 5}, {"point": "数字化巡河，闭环整改", "synonyms": ["巡河APP", "拍照上传", "派单整改", "限期销号"], "score": 5}, {"point": "发动群众参与，举报有奖", "synonyms": ["民间护河员", "举报奖励", "群众监督", "村民参与"], "score": 4}, {"point": "财政投入，清淤修复", "synonyms": ["专项资金", "河道清淤", "生态修复", "岸线修复"], "score": 3}, {"point": "严格考核，结果挂钩", "synonyms": ["纳入考核", "评优挂钩", "考核问责", "督查考核"], "score": 3}], "referenceAnswer": "一是织密责任网。建立县乡村三级河长体系，每条河设立公示牌，公开河长姓名、职责和监督电话。二是数字巡河。河长用APP打卡巡河，问题拍照上传、系统派单、限期销号。三是群防群治。聘请62名村民任护河员，举报偷排、非法捕捞查实有奖。四是投入保障。财政每年安排专项资金，两年清理垃圾1.2万吨、修复岸线15公里。五是考核压责。河长制纳入乡镇综合考核，结果与干部评优挂钩。", "tips": "命题人提示：河长制做法可按“责任体系—巡河机制—群众参与—投入—考核”五环节概括，注意“限期整改销号”体现闭环管理。"}, {"id": "shl-13", "module": "shenlun", "category": "归纳概括", "exam": "江苏", "year": 2021, "source": "2021年江苏省考B类第一题（材料改写）", "title": "G市志愿服务工作的亮点", "material": ["材料一：G市建成市、区、街道、社区四级志愿服务网络，注册志愿者达58万人。市文明办开发志愿服务小程序，市民可按需点单，平台就近匹配志愿者，服务结束后双向评价。", "材料二：市里推行志愿服务积分制，志愿者凭积分可免费乘坐公交、兑换景区门票，全市126家爱心商户加入积分联盟。针对独居老人，社区组建“敲门嫂”队伍，每周上门探望；针对放学后无人看管的儿童，开设“四点半课堂”，由退休教师和大学生志愿者轮流看护。去年全市志愿服务时长累计突破2000万小时。", "材料三：志愿服务也面临成长烦恼。有志愿者反映，活动通知临时、服务记录不全等问题影响积极性。市里为此升级小程序，实现活动发布、报名签到、时长记录全流程线上化，服务记录终身可查。", "材料四：一位受助老人说：“志愿者比亲人还亲，每周都来看我。”社区书记介绍，敲门嫂队伍已从8人发展到35人，实现了独居老人探访全覆盖。", "市里还把志愿服务纳入文明单位创建指标，推动机关企事业单位党员带头注册。"], "question": "根据给定资料，概括G市志愿服务工作的亮点。（20分）要求：全面、准确、有条理，不超过250字。", "wordLimit": 250, "scorePoints": [{"point": "健全四级网络，队伍规模大", "synonyms": ["四级网络", "注册志愿者多", "组织体系健全"], "score": 5}, {"point": "数字点单，精准匹配", "synonyms": ["小程序点单", "就近匹配", "双向评价", "供需对接"], "score": 5}, {"point": "积分激励，商家联盟", "synonyms": ["积分制", "兑换福利", "爱心商户", "激励机制"], "score": 5}, {"point": "聚焦重点人群，服务精准", "synonyms": ["敲门嫂", "四点半课堂", "独居老人", "儿童看护"], "score": 5}], "referenceAnswer": "一是组织健全。建成四级志愿服务网络，注册志愿者58万人。二是供需精准。小程序按需点单、就近匹配志愿者，服务双向评价。三是激励有效。推行积分制，可乘公交、换门票，126家商户加入积分联盟。四是服务暖心。组建敲门嫂队伍每周探望独居老人，开设四点半课堂看护放学儿童，全年服务时长超2000万小时。", "tips": "命题人提示：亮点题突出“新”和“实”，积分激励和点单匹配是机制创新，敲门嫂、四点半课堂是服务精准，两类都要点到。"}, {"id": "shl-14", "module": "shenlun", "category": "归纳概括", "exam": "国考", "year": 2020, "source": "2020年国考副省级第一题（材料改写）", "title": "D村脱贫攻坚的主要举措", "material": ["材料一：D村地处深山，曾是深度贫困村。驻村工作队逐户摸底，为每户制定帮扶计划，落实低保、医疗救助等政策，全村因病致贫户全部纳入健康扶贫范围。", "材料二：工作队争取资金修通7公里出山公路，结束村民肩挑背驮的历史。依托山上茶园，成立茶叶专业合作社，统一收购、统一加工、统一销售，带动58户贫困户户均年增收1.6万元。村里组织剩余劳动力参加电工、厨师等技能培训，累计输出务工人员120人。教育扶贫方面，村里落实雨露计划，23名贫困学生获得补助，无一辍学。", "材料三：脱贫摘帽不是终点。驻村工作队又制定了巩固提升计划：扩建茶叶加工车间，注册绿色食品标志，发展茶旅融合项目。老支书说：“路通了，产业有了，年轻人的心也留住了。”", "材料四：县乡村振兴局负责人评价，D村的脱贫路子扎实，既输血又造血，既扶贫又扶志，是可持续脱贫的样板。", "工作队还建起村史馆，记录脱贫历程，激励村民感恩奋进。", "如今的D村，茶园连片、新房错落，成了远近闻名的示范村。"], "question": "根据给定资料，概括D村脱贫攻坚的主要举措。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "精准摸底，一户一策", "synonyms": ["逐户摸底", "帮扶计划", "精准施策", "因户施策"], "score": 4}, {"point": "落实兜底政策，健康扶贫", "synonyms": ["低保", "医疗救助", "政策兜底", "健康扶贫"], "score": 4}, {"point": "改善基础设施，修路通路", "synonyms": ["修公路", "基础设施", "出行条件"], "score": 4}, {"point": "发展特色产业，合作经营", "synonyms": ["合作社", "茶叶产业", "统一收购", "产业扶贫"], "score": 5}, {"point": "技能培训促就业，劳务输出", "synonyms": ["技能培训", "务工输出", "就业扶贫"], "score": 3}], "referenceAnswer": "一是精准帮扶。逐户摸底制定帮扶计划，因病致贫户全部纳入健康扶贫。二是政策兜底。落实低保、医疗救助等政策。三是基础先行。修通7公里出山公路，结束肩挑背驮历史。四是产业造血。成立茶叶专业合作社，统一收购加工销售，58户户均增收1.6万元。五是就业增收。组织技能培训，输出务工120人；落实雨露计划，23名贫困生获补助，无一辍学。", "tips": "命题人提示：脱贫举措按“精准识别—兜底—基建—产业—就业教育”五方展开，教育扶贫内容虽短但易漏，注意合并表述。"}, {"id": "shl-15", "module": "shenlun", "category": "归纳概括", "exam": "山东", "year": 2024, "source": "2024年山东省考第一题（材料改写）", "title": "K社区基层治理的新探索", "material": ["材料一：K社区把辖区划分为12个网格，每个网格配备网格员、民警、物业管家和楼栋长，建立“一格四员”机制。居民扫码进入网格微信群，反映问题当天响应，小事网格内办结，大事社区吹哨、部门报到。", "材料二：社区搭建“居民议事厅”，每月围绕停车、绿化等议题协商，去年议定事项43件，办结率100%。社区还引入两家社会组织，承接养老托幼、心理疏导等专业服务；组建“银发调解队”，由退休干部、老党员担任调解员，去年化解邻里纠纷87起，实现小事不出楼栋、大事不出社区。", "材料三：治理创新也激发了居民热情。退休教师陈阿姨是银发调解队队长，她说：“大家信得过我，我就把话说开，矛盾自然化解。”社区还开设“议事厅”线上版，上班族也能参与议事。", "材料四：市民政局将K社区经验写入社区治理指引，在全市推广“一格四员”模式。专家指出，基层治理的关键是让居民从旁观者变成参与者。", "社区每月公布网格事项办理情况，接受居民监督。", "社区还建立网格员培训制度，每月开展业务比武，提升服务本领。"], "question": "根据给定资料，概括K社区基层治理的新探索。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "网格化管理，一格四员", "synonyms": ["网格化", "一格四员", "网格员", "分格管理"], "score": 5}, {"point": "线上响应，吹哨报到", "synonyms": ["网格微信群", "当天响应", "部门报到", "接诉即办"], "score": 4}, {"point": "居民议事，协商共治", "synonyms": ["议事厅", "协商议事", "居民自治", "议定事项"], "score": 4}, {"point": "引入社会组织，专业服务", "synonyms": ["社会组织", "购买服务", "养老托幼", "专业服务"], "score": 4}, {"point": "银发调解，化解纠纷", "synonyms": ["调解队", "老党员调解", "矛盾化解", "纠纷调解"], "score": 3}], "referenceAnswer": "一是网格精细。划分12个网格，配齐网格员、民警、物业管家、楼栋长，实行一格四员。二是响应迅速。居民扫码进群反映问题当天响应，小事格内办结，大事吹哨部门报到。三是协商共治。每月开居民议事厅议停车、绿化等事项，去年议定43件全部办结。四是专业服务。引入两家社会组织承接养老托幼、心理疏导。五是矛盾化解。银发调解队去年化解邻里纠纷87起，小事不出楼栋。", "tips": "命题人提示：“新探索”重在机制创新，一格四员、吹哨报到、议事厅、银发调解都是可复制的机制，概括时保留机制名称。"}, {"id": "shl-16", "module": "shenlun", "category": "归纳概括", "exam": "江苏", "year": 2024, "source": "2024年江苏省考A类第一题（材料改写）", "title": "M市非遗保护传承工作的做法", "material": ["材料一：M市组织力量对全市非遗项目开展普查，建立包含217个项目的数据库，为每位代表性传承人建立档案，发放年度传习补助。", "材料二：市里开设非遗工坊，采取“传承人+学徒”模式带徒授艺，累计培养青年传承人140余名。非遗进校园活动覆盖全市86所中小学，剪纸、泥塑等课程进入课后服务。依托古城景区设立非遗展示街区，20个项目的传承人现场展演，游客可体验制作。市里还推动非遗与文创结合，开发的蓝印花布文创产品年销售额超千万元，让老手艺有了新市场。", "材料三：非遗保护也遇到传承难题。部分项目传承人年事已高，年轻人不愿学。市里为此提高传习补助标准，把带徒数量与补助挂钩，鼓励传承人多带徒、带好徒。", "材料四：一位90后学徒说：“跟着师傅学剪纸，一个月能挣四五千，还能传承手艺，我觉得挺值。”市文旅局负责人表示，非遗只有走进生活，才能走得更远。", "市里还举办非遗购物节，线上线下同步展销，助力传承人增收。", "下一步，市里计划建设非遗馆，让市民在家门口感受传统文化魅力。"], "question": "根据给定资料，概括M市非遗保护传承工作的做法。（20分）要求：全面、准确、有条理，不超过250字。", "wordLimit": 250, "scorePoints": [{"point": "普查建档，摸清家底", "synonyms": ["普查", "数据库", "建立档案", "摸底调查"], "score": 5}, {"point": "补助传习，保障传承", "synonyms": ["传习补助", "传承人保障", "资金支持"], "score": 4}, {"point": "带徒授艺，培养新人", "synonyms": ["非遗工坊", "师徒传承", "培养青年传承人"], "score": 5}, {"point": "非遗进校园，从娃娃抓起", "synonyms": ["进校园", "课后服务", "中小学课程"], "score": 3}, {"point": "文旅融合，活态传承", "synonyms": ["展示街区", "景区展演", "文创开发", "市场化"], "score": 3}], "referenceAnswer": "一是摸清家底。普查建立217个项目的数据库，为传承人建档并发放年度传习补助。二是薪火相传。开设非遗工坊，以传承人带学徒模式培养青年传承人140余名。三是教育浸润。非遗进校园覆盖86所中小学，剪纸、泥塑进入课后服务。四是活态传承。在古城景区设展示街区，20个项目现场展演；推动非遗文创化，蓝印花布产品年销售额超千万元。", "tips": "命题人提示：非遗题按“保护—传承—教育—活化”逻辑概括，普查建档是基础性工作，文创与景区展演体现让非遗“活起来”。"}, {"id": "shl-17", "module": "shenlun", "category": "综合分析", "exam": "国考", "year": 2022, "source": "2022年国考副省级第二题（材料改写）", "title": "谈谈对“城市的温度”的理解", "material": ["材料一：有学者提出，衡量一座城市的发展水平，不仅要看高楼大厦的高度，更要看“城市的温度”。所谓城市的温度，是指城市对人的关怀程度：盲道是否畅通、公厕是否好找、政务大厅有没有为老人保留人工窗口、外卖骑手有没有地方歇脚。", "材料二：近年来，不少城市在细节处体现关怀：地铁站点配备无障碍电梯并安排专人引导；环卫工人驿站提供热水和微波炉；公园长椅加装木质的座垫，冬天不再冰凉。市民说，这些小事让人感觉被尊重、被善待，城市因此更有归属感。也有城市重面子轻里子，广场宽阔气派，但座椅稀少、遮阳避雨设施缺乏，群众评价“好看不好用”。", "材料三：城市规划专家指出，城市的温度来自治理的精度。温度不是喊出来的，而是一件一件实事垒起来的。有的城市开展“城市体检”，把群众感受作为重要指标；有的城市邀请市民给市政设施“挑刺”，发现问题及时整改。", "材料四：也有市民担心，温度工程会不会一阵风？专家回应，关键在制度化：把无障碍建设、适老化改造纳入城市规划刚性要求，温度才能持久。"], "question": "结合给定资料，谈谈你对“城市的温度”的理解。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "城市温度指城市对人的关怀程度", "synonyms": ["对人的关怀", "以人为本", "人性化程度", "关怀程度"], "score": 6}, {"point": "体现在细节和民生小事上", "synonyms": ["细节关怀", "民生小事", "无障碍设施", "便民细节"], "score": 5}, {"point": "让市民有归属感、被尊重", "synonyms": ["归属感", "被尊重", "被善待", "幸福感"], "score": 5}, {"point": "不能重面子轻里子，要实用", "synonyms": ["重面子轻里子", "好看不好用", "实用导向", "避免形象工程"], "score": 4}], "referenceAnswer": "城市的温度，是指城市对人的关怀程度，体现以人为本的发展理念。它往往藏在细节里：盲道是否畅通、政务大厅是否保留人工窗口、骑手是否有处歇脚。有温度的城市在小事上善待每个人，让市民感到被尊重，从而产生归属感和幸福感。反之，若重面子轻里子，广场虽气派却缺少座椅和遮雨设施，就是好看不好用。因此，城市建设应从群众身边小事做起，把关怀落到细节，让发展更有温度。", "tips": "命题人提示：词句理解题按“是什么—为什么—怎么办”作答，先给定义，再谈表现与意义，最后点出实践要求。"}, {"id": "shl-18", "module": "shenlun", "category": "综合分析", "exam": "江苏", "year": 2022, "source": "2022年江苏省考A类第二题（材料改写）", "title": "谈谈对“基层减负要减掉形式之负”的认识", "material": ["材料一：某乡干部反映，一年要填报各类报表300多份，同一数据不同部门反复索要；有的检查考核重痕迹轻实绩，工作群打卡、拍照留痕成了主要任务。基层干部疲于应付，服务群众的时间被大量挤占。", "材料二：中央为基层减负以来，各地清理规范报表和考核事项。F县将部门报表整合为一张综合表，数据一次采集、多方共享；考核改为看实绩、听民声，取消不必要的拍照留痕要求。减负后，乡镇干部下村时间平均每周增加两天，群众满意度明显提升。干部们说，减掉的是形式之负，增加的是实干之效。", "材料三：一位乡镇干部算了一笔账：减负前，他每周要参加七八个会议，填报十几套报表；减负后，会议少了三成，报表合并成一张综合表，下村时间明显多了。他说：“现在能把更多精力放在帮群众解决实际问题上。”", "材料四：专家指出，减负不是减责任，而是把干部从形式主义中解放出来，把时间还给群众，把功夫下到实处。减负与实干相辅相成，减掉形式之负，方能增添实干之效。", "有干部感慨，减负后“表少了、会少了，心气顺了，劲更足了”。"], "question": "结合给定资料，谈谈你对“基层减负要减掉形式之负”的认识。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "形式主义加重基层负担", "synonyms": ["报表多", "重痕迹轻实绩", "反复填表", "文山会海"], "score": 5}, {"point": "挤占服务群众的时间精力", "synonyms": ["疲于应付", "挤占时间", "脱离群众", "影响服务"], "score": 5}, {"point": "减负须整合报表、改进考核", "synonyms": ["整合报表", "数据共享", "考核看实绩", "取消留痕"], "score": 5}, {"point": "减负目的是让干部实干为民", "synonyms": ["增加实干", "下村时间增加", "满意度提升", "实干之效"], "score": 5}], "referenceAnswer": "形式之负，指报表反复填、考核重痕迹等形式主义做法给基层造成的负担。其危害在于让干部疲于应付、挤占服务群众的时间，损害干群关系。减掉形式之负，一要整合报表、数据共享，变多头索要为一次采集；二要改进考核，看实绩、听民声，取消不必要的留痕。减负的落脚点是让干部把精力放到实干上，F县减负后干部下村时间每周增加两天、群众满意度提升，正说明减掉形式之负，方能增添实干之效。", "tips": "命题人提示：认识类题目要答出内涵、危害、对策、目的四个层次，材料中的对比（减负前后）是作答关键。"}, {"id": "shl-19", "module": "shenlun", "category": "综合分析", "exam": "国考", "year": 2021, "source": "2021年国考市地级第二题（材料改写）", "title": "谈谈“种树者必培其根”对青年成长的启示", "material": ["材料一：古语云：“种树者必培其根，种德者必养其心。”树木生长，根深方能叶茂；人的成长，根基不牢，地动山摇。有青年干部名校毕业，却嫌基层琐碎，工作浮在面上，几年过去仍难独当一面；也有青年在乡镇一线摸爬滚打，练出了群众工作的真本领。", "材料二：一位老支书说，年轻人成长就像种树，不能只想着枝繁叶茂，要先扎根。根，是理想信念，是过硬本领，是与群众的感情。培根的过程或许缓慢，但根扎稳了，风雨来了才站得住。", "材料三：一位选调生回忆，刚到村里时连方言都听不懂，群众工作无从下手。两年间，他跟着老支书走村入户，学会了跟群众打交道的本领，也懂得了政策落地的酸甜苦辣。他说：“基层是最好的课堂，群众是最好的老师。”", "材料四：组织部门负责人表示，将完善年轻干部基层锻炼制度，让更多年轻人在乡村振兴、基层治理一线经风雨、见世面、长才干。", "该选调生如今已能独当一面，被群众亲切称为“村里人”。", "组织部门还建立了导师帮带制度，为每名选调生配备一名基层经验丰富的导师。"], "question": "结合给定资料，谈谈“种树者必培其根”对青年成长的启示。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "成长须先固本培元，打牢根基", "synonyms": ["打牢根基", "固本培元", "根基不牢地动山摇", "先扎根"], "score": 6}, {"point": "根基是理想信念、本领和群众感情", "synonyms": ["理想信念", "过硬本领", "群众感情", "扎根基层"], "score": 5}, {"point": "戒除浮躁，不能急功近利", "synonyms": ["戒浮躁", "不浮在面上", "不急功近利", "沉下心"], "score": 5}, {"point": "在实践中磨砺，久久为功", "synonyms": ["基层磨砺", "摸爬滚打", "缓慢积累", "久久为功"], "score": 4}], "referenceAnswer": "种树培根，喻指人的成长必须先打牢根基。启示有四：一是成长要固本培元，根深方能叶茂，根基不牢、地动山摇。二是青年的根，是坚定的理想信念、过硬的本领和与群众的感情，须自觉培植。三要戒除浮躁，不能像部分青年干部那样嫌基层琐碎、工作浮在面上，而应沉下身子。四要在基层一线摸爬滚打、经受磨砺，培根虽缓，根稳则风雨不惧，成长方能行稳致远。", "tips": "命题人提示：启示题要由喻入理，先解释喻义，再分条给启示；材料正反两个青年事例是提炼启示的依据。"}, {"id": "shl-20", "module": "shenlun", "category": "综合分析", "exam": "浙江", "year": 2022, "source": "2022年浙江省考第二题（材料改写）", "title": "分析T县“直播助农”由热转冷的原因", "material": ["材料一：前年，T县的苹果借助直播走红，单场销售破十万单。但好景不长，去年多场直播销量跌回原点。果农老周说，订单暴增时发货跟不上，烂果、坏果多，差评一片。", "材料二：县里几家直播团队各自为战，互相压价，把价格打穿后只能以次充好，消费者收到货发现大小不一、口感参差。产品缺乏分级标准，包装简陋，运输损耗率高。此外，直播内容同质化严重，都是“悲情营销”“喊麦叫卖”，观众审美疲劳。有电商专家指出，直播只是渠道，产品品质和供应链才是根本，T县恰恰在根本上下功夫不够。", "材料三：果农们也在反思。有人开始给苹果分级，大果精装卖高价，小果加工果汁；有人联合起来建冷库，错峰销售。老周说：“光靠主播喊不行，果子得自己硬气。”", "材料四：县里已出台直播电商规范发展意见，推动建立产品分级、仓储物流、售后保障体系，引导直播助农从“一时火”走向“一直火”。", "县里还引进分拣线，苹果按大小、色泽自动分级，优质果率明显提升。", "县里还注册了区域公用品牌，统一包装标识，提升产品辨识度。"], "question": "结合给定资料，分析T县“直播助农”由热转冷的原因。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "发货能力不足，品控差引发差评", "synonyms": ["发货慢", "烂果坏果", "品控差", "差评"], "score": 5}, {"point": "各自为战，恶性压价", "synonyms": ["互相压价", "各自为战", "恶性竞争", "低价竞争"], "score": 5}, {"point": "缺乏分级标准和包装，损耗高", "synonyms": ["无分级标准", "包装简陋", "运输损耗", "品质参差"], "score": 5}, {"point": "营销同质化，观众审美疲劳", "synonyms": ["内容同质化", "悲情营销", "审美疲劳", "创新不足"], "score": 3}, {"point": "重渠道轻品质，供应链薄弱", "synonyms": ["重渠道轻产品", "供应链不足", "忽视品质", "根本问题"], "score": 2}], "referenceAnswer": "一是供给端乏力。订单暴增后发货跟不上，烂果坏果多，差评损害口碑。二是竞争失序。直播团队各自为战、互相压价，低价之下以次充好。三是标准化缺失。产品无分级标准，包装简陋，运输损耗高，品质参差。四是营销乏力。内容同质化，悲情营销、喊麦叫卖令观众审美疲劳。五是根本错位。重直播渠道、轻产品品质和供应链建设，本末倒置，热度难以持续。", "tips": "命题人提示：原因分析按“供给—竞争—标准—营销—根本”逐层展开，最后一条是专家点出的根本原因，务必单独成条。"}, {"id": "shl-21", "module": "shenlun", "category": "综合分析", "exam": "江苏", "year": 2023, "source": "2023年江苏省考B类第二题（材料改写）", "title": "评价“网红县长带货”现象", "material": ["材料一：某县副县长走进直播间为本地蜜柚代言，单场销售30万斤，网友点赞“接地气”。也有人质疑：县长该干好政务，带货是不是不务正业？是不是作秀？", "材料二：该县长回应，带货是利用周末时间，目的是帮农户打开销路，示范带动更多干部触网。带货后，县里蜜柚收购价每斤提高0.8元，2000多户果农受益。也有专家提醒，干部带货是应急之举，长远之计在于培育本土电商人才和经营主体，不能干部一走，销量就断崖式下跌。", "材料三：该县长带货并非心血来潮。此前县里调研发现，蜜柚品质好但销路窄，收购价多年徘徊。县长带头直播后，县里顺势培育了12支本土直播队伍，培训果农300余人次。", "材料四：对于“作秀”的质疑，多数网友并不认同。有人留言：“能帮果农卖货的就是好县长。”也有网友提醒：“别让形式大于内容，关键看果农的口袋鼓不鼓。”", "县里同步完善物流体系，快递进村全覆盖，发货时效提升一倍。", "县里还把直播带货纳入干部培养内容，鼓励更多干部学电商、懂电商。"], "question": "结合给定资料，评价“网红县长带货”这一现象。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "带货有积极意义，助农增收", "synonyms": ["打开销路", "助农", "提高收购价", "果农受益"], "score": 5}, {"point": "示范带动干部转变观念触网", "synonyms": ["示范带动", "干部触网", "转变观念", "带头作用"], "score": 5}, {"point": "质疑有一定道理，须守边界", "synonyms": ["不务正业质疑", "作秀质疑", "干好主业", "把握边界"], "score": 4}, {"point": "是应急之举，须培育长效机制", "synonyms": ["应急之举", "培育人才", "长效机制", "防止断崖下跌"], "score": 6}], "referenceAnswer": "网红县长带货总体值得肯定，但需理性看待。积极面：一是解了燃眉之急，单场售出蜜柚30万斤，收购价每斤提高0.8元，2000余户果农受益；二是起了示范作用，带动更多干部重视电商、转变观念。同时，对不务正业、作秀的质疑提醒干部须摆正位置，带货应利用业余时间、服务大局。更要看到，干部带货是应急之举，长远须培育本土电商人才和经营主体，避免人走单断，实现从流量帮扶到产业自立。", "tips": "命题人提示：评价题要一分为二，先肯定意义，再回应质疑，最后指出局限与方向，结论须明确不骑墙。"}, {"id": "shl-22", "module": "shenlun", "category": "综合分析", "exam": "国考", "year": 2023, "source": "2023年国考副省级第二题（材料改写）", "title": "谈谈对“把论文写在祖国大地上”的理解", "material": ["材料一：某农业专家常年在田间指导，培育的良种推广数百万亩，农民叫他“田教授”。他说，论文不只要写在期刊上，更要写在祖国大地上，让农民的粮袋子鼓起来。", "材料二：也有科研人员成果束之高阁，评审只数论文篇数，成果与需求两张皮。近年来，国家推行科技成果转化激励政策，把服务产业成效纳入评价，一批科研人员走进企业、下到田间，专利转化率明显提升。科技小院的学生们说，在地里做研究，才知道农民需要什么，研究才有生命力。", "材料三：田教授的故事激励了许多青年科研人员。某农业大学在田间地头设立科技小院，研究生吃住在村，白天进地、晚上写报告，毕业论文全是真问题。农民说：“这些娃娃接地气，讲的法子管用。”", "材料四：也有科研人员坦言，下田间意味着论文产出变慢、考核吃亏。专家建议，完善分类评价机制，让做基础研究的潜心研究，让做应用推广的安心服务，各得其所。", "科技小院已推广到全县8个乡镇，带动农户增收明显。", "学校还聘请田教授担任产业导师，定期回校分享实践经验。"], "question": "结合给定资料，谈谈你对“把论文写在祖国大地上”的理解。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "科研要面向需求、服务实践", "synonyms": ["面向需求", "服务实践", "成果落地", "解决实际问题"], "score": 6}, {"point": "反对成果束之高阁、评价唯论文", "synonyms": ["束之高阁", "唯论文", "两张皮", "评价导向偏差"], "score": 5}, {"point": "完善评价激励，引导成果转化", "synonyms": ["纳入评价", "转化激励", "政策引导", "考核改革"], "score": 5}, {"point": "在实践中研究才更有生命力", "synonyms": ["科技小院", "田间研究", "生命力", "实践出真知"], "score": 4}], "referenceAnswer": "把论文写在祖国大地上，是说科研的价值在于服务实践、造福人民。其一，科研要面向需求，像田教授那样把成果送到田间，让农民得实惠。其二，要纠偏成果束之高阁、评价唯论文的倾向，防止科研与需求两张皮。其三，国家以转化激励和服务成效纳入评价，引导科研人员下企业、进田间，专利转化率随之提升。其四，实践出真知，科技小院的经历说明，在地里做研究才知道农民需要什么，成果才更有生命力。", "tips": "命题人提示：理解题抓住“大地”这一意象，即实践与需求；作答时正反对照，突出评价导向改革这一关键举措。"}, {"id": "shl-23", "module": "shenlun", "category": "综合分析", "exam": "山东", "year": 2023, "source": "2023年山东省考第二题（材料改写）", "title": "分析“社区食堂”受追捧又遇冷的原因并谈启示", "material": ["材料一：某市社区食堂开业时，两荤两素8元的价格吸引大批老人排队，日均就餐超300人次。但半年后，多家食堂经营困难，有的关门歇业。", "材料二：经营者算账，房租、人工成本高，8元套餐几乎无利润，全靠补贴难以为继。年轻人嫌菜品单一不来，老人对口味变化也有意见。而隔壁城市的社区食堂采取“公建民营”，政府免费提供场地，食堂对内保本微利、对外市场化经营，还承接外卖和单位团餐，实现收支平衡、持续运营。", "材料三：社区食堂的困境引发讨论。有人认为，民生工程不能一关了之；也有人指出，光靠情怀和补贴走不远，必须找到可持续的运营模式。", "材料四：隔壁城市的经验给了启示：政府提供场地、水电优惠，食堂专心做好饭；针对年轻人推出套餐，针对老人推出软烂餐；食堂还成了老人的社交空间，人气越来越旺。市民政局表示，将推广公建民营模式，让社区食堂办得下去、办得长久。", "该市还引入社会捐赠，设立社区食堂公益基金，弥补运营缺口。", "食堂还推出生日面、长寿面等暖心服务，赢得老人点赞。"], "question": "结合给定资料，分析社区食堂“受追捧又遇冷”的原因，并简要谈谈启示。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "受追捧：价格实惠，契合老人需求", "synonyms": ["价格低", "实惠", "契合需求", "老人欢迎"], "score": 4}, {"point": "遇冷：成本高、定价低，难以为继", "synonyms": ["成本高", "无利润", "依赖补贴", "经营困难"], "score": 5}, {"point": "遇冷：菜品单一，客源不足", "synonyms": ["菜品单一", "客源少", "口味意见", "吸引力不足"], "score": 4}, {"point": "启示：公建民营，降本减负", "synonyms": ["公建民营", "免费场地", "降低成本"], "score": 3}, {"point": "启示：多元经营，市场化造血", "synonyms": ["市场化经营", "对外营业", "团餐外卖", "自我造血"], "score": 4}], "referenceAnswer": "受追捧，在于两荤两素8元价格实惠，精准契合老人就餐需求。遇冷，一是房租人工成本高、定价过低，利润微薄，依赖补贴难以为继；二是菜品单一，年轻人不来，老人有意见，客源不足。启示：一要创新机制，推行公建民营，政府免费供场地，为经营减负；二要增强造血能力，对内保本微利、对外市场化经营，承接外卖团餐，以多元收入实现可持续运营，让民生实事办得长久。", "tips": "命题人提示：本题两问，原因分“热”“冷”两面，启示从隔壁城市成功经验中提炼，注意冷的原因与启示要一一呼应。"}, {"id": "shl-24", "module": "shenlun", "category": "综合分析", "exam": "江苏", "year": 2021, "source": "2021年江苏省考A类第二题（材料改写）", "title": "比较两个乡镇文旅开发思路的差异并评析", "material": ["材料一：A镇拥有千年古村，开发时坚持修旧如旧，聘请老工匠用传统工艺修缮古建，保留原住民生活业态，酿坊、油坊照常经营，游客看到的是“活着的古村”。开发节奏慢，但口碑持续发酵，回头客多。", "材料二：B镇同样有古村资源，为快速见效，推平部分老宅建起仿古商业街，引进全国雷同的小吃和纪念品店，原住民整体搬迁。开业时人气火爆，但游客很快发现“千村一面”，两年后客流锐减，商铺大量空置。", "材料三：两地差异背后是发展理念的差异。A镇干部说：“古村是老祖宗留下的家底，我们只是管家，不能败家。”B镇干部则坦言：“当时急于出政绩，把好经念歪了。”", "材料四：如今，B镇也在纠偏，请来规划团队重新编制保护规划，逐步恢复古村风貌。专家指出，文旅开发要算长远账、文化账，杀鸡取卵式开发终将得不偿失。", "B镇还组织干部到A镇跟班学习，转变开发理念。", "B镇还建立了古村保护专家咨询制度，重大改造方案须经专家评审。", "专家建议，古镇开发应建立负面清单，明确禁止大拆大建、拆真建假。"], "question": "结合给定资料，比较A镇与B镇文旅开发思路的差异，并作简要评析。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "A镇保护优先，修旧如旧", "synonyms": ["修旧如旧", "传统工艺", "保护性开发", "保留原貌"], "score": 4}, {"point": "A镇保留生活业态，原真性", "synonyms": ["原住民", "活着的古村", "生活业态", "原真性"], "score": 4}, {"point": "B镇大拆大建，商业化同质", "synonyms": ["拆老宅建仿古街", "同质化", "千村一面", "过度商业"], "score": 4}, {"point": "B镇赶工期求快，搬迁居民", "synonyms": ["快速见效", "整体搬迁", "急功近利"], "score": 3}, {"point": "评析：保护本底方能持续，急功近利难长久", "synonyms": ["口碑持续", "回头客多", "客流锐减", "可持续"], "score": 5}], "referenceAnswer": "差异：A镇坚持保护优先，修旧如旧，用传统工艺修缮，保留原住民和生活业态，古村是“活”的；B镇追求快速见效，大拆大建，建仿古商业街，业态同质，原住民整体搬迁。评析：文旅开发的根基是原真性和文化本底。A镇虽节奏慢，但留住了村魂，口碑发酵、回头客多，走的是可持续之路；B镇千村一面，丢了特色，热度昙花一现，客流锐减。可见，古镇开发须敬畏历史、留住烟火气，急功近利终将被市场淘汰。", "tips": "命题人提示：比较题先分条对比差异，再作评析；评析要结合两镇结果（回头客多与商铺空置）印证观点。"}, {"id": "shl-25", "module": "shenlun", "category": "综合分析", "exam": "国考", "year": 2024, "source": "2024年国考市地级第二题（材料改写）", "title": "谈谈对“基层治理既要有力度也要有温度”的理解", "material": ["材料一：某市整治占道经营，执法队员先劝导、再警告、后处罚，对困难摊贩引导进入规范摊区并减免摊位费。摊主说，执法有力度也有人情味。", "材料二：也有地方治理简单化：为迎检一夜之间清空全部流动摊贩，市容达标了，群众买菜却要多走两公里；有的为图省事一禁了之，电动车禁行、鞭炮禁放、摊贩禁摆，群众意见大。专家指出，治理的最终目的是群众满意，力度是手段，温度是底色，二者不可偏废。", "材料三：该市还推行“综合查一次”改革，多个部门联合执法，减少对企业正常经营的打扰。执法队员说：“处罚不是目的，规范经营才是。”对轻微违法，推行首违不罚、轻微免罚清单。", "材料四：专家评价，有力度有温度的执法，考验的是治理智慧。力度体现法治底线，温度体现为民初心，二者统一于严格规范公正文明执法之中。", "该市还聘请人大代表、政协委员担任执法监督员，倒逼执法规范。", "该市还开展执法技能大练兵，提升执法队伍专业水平。", "该市还发布文明执法指引，规范执法用语和行为，让执法既有尺度又有温度。"], "question": "结合给定资料，谈谈你对“基层治理既要有力度也要有温度”的理解。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "力度指依法依规、动真碰硬", "synonyms": ["依法治理", "严格执法", "动真碰硬", "规范秩序"], "score": 5}, {"point": "温度指人性化执法、体恤困难", "synonyms": ["人性化", "劝导优先", "减免费用", "体恤困难群体"], "score": 5}, {"point": "简单化一刀切损害群众利益", "synonyms": ["一禁了之", "简单化", "一刀切", "群众不便"], "score": 5}, {"point": "治理目的是群众满意，两手都要抓", "synonyms": ["群众满意", "不可偏废", "刚柔并济", "目的与手段"], "score": 5}], "referenceAnswer": "基层治理的力度，指依法依规、动真碰硬，对违法行为敢管敢治，维护公共秩序；温度，指执法人性化，先劝导后处罚，对困难摊贩引导帮扶、减免费用。反面看，简单化治理一禁了之，虽市容达标，却让群众买菜多走两公里，损害了利益。治理的最终目的是群众满意，力度是手段，温度是底色。因此，基层治理应刚柔并济：该管的一定管住，能帮的尽力帮好，让执法既有硬度，也有人情味。", "tips": "命题人提示：理解题先分别界定“力度”“温度”，再用反面材料说明偏废之害，最后落到二者统一的结论。"}, {"id": "shl-26", "module": "shenlun", "category": "综合分析", "exam": "浙江", "year": 2024, "source": "2024年浙江省考第二题（材料改写）", "title": "谈谈“数字赋能”给乡村治理带来的变化", "material": ["材料一：N村推广“数字乡村”平台，村民手机上可查看村务公开、三资管理，集体账目笔笔可查。独居老人家中安装一键呼叫设备，村网格员5分钟内响应。田间传感器实时监测墒情，浇水施肥按数据来。", "材料二：村支书感慨，过去开会靠喇叭喊、账目靠墙上贴，现在数据多跑路、干部少跑腿。但也有村民担心，老人不会用智能手机会不会被数字化抛下？平台信息更新不及时会不会变成新形式主义？县里回应，已为老年人保留线下渠道，并建立平台运维责任制。", "材料三：数字乡村建设也带来新变化。村里开会，外出务工的村民通过视频同步参加；村务公开从“墙上贴”变成“掌上看”，在外游子也能监督家乡事务。", "材料四：县里还组织志愿者开设智能手机课堂，教老人视频通话、网上挂号。一位老人学会后感慨：“数字时代，咱也不能掉队。”", "村里还为不会用智能手机的老人发放一键呼叫终端，实现服务全覆盖。", "村里还建设数字大屏，实时展示村务、产业和便民服务信息。", "县里还建立数字乡村运维基金，保障平台长期稳定运行。"], "question": "结合给定资料，谈谈“数字赋能”给乡村治理带来的变化。（20分）要求：全面、准确、有条理，不超过300字。", "wordLimit": 300, "scorePoints": [{"point": "村务透明，监督便捷", "synonyms": ["村务公开", "三资管理", "账目可查", "阳光村务"], "score": 5}, {"point": "服务响应更快，关爱精准", "synonyms": ["一键呼叫", "快速响应", "关爱老人", "精准服务"], "score": 5}, {"point": "生产智能化，按数据作业", "synonyms": ["传感器", "墒情监测", "智慧农业", "数据种田"], "score": 4}, {"point": "干部减负，效率提升", "synonyms": ["数据多跑路", "干部少跑腿", "效率提升", "减负"], "score": 3}, {"point": "须防范数字鸿沟和新形式主义", "synonyms": ["数字鸿沟", "保留线下渠道", "运维责任制", "防止形式主义"], "score": 3}], "referenceAnswer": "数字赋能带来四方面变化：一是监督透明，村务、三资上网公开，集体账目笔笔可查；二是服务提速，独居老人一键呼叫，网格员5分钟响应，关爱更精准；三是生产升级，田间传感器监测墒情，浇水施肥按数据来；四是治理提效，数据多跑路、干部少跑腿。同时须清醒：要为不会用智能手机的老人保留线下渠道，跨越数字鸿沟；建立平台运维责任制，防止信息不更新沦为新的形式主义。", "tips": "命题人提示：变化题以正面成效为主，但材料二的担忧是重要提醒，答出防范数字鸿沟与形式主义才算全面。"}, {"id": "shl-27", "module": "shenlun", "category": "贯彻执行", "exam": "国考", "year": 2022, "source": "2022年国考市地级第三题（材料改写）", "title": "撰写节约粮食倡议书", "material": ["材料一：某市餐饮浪费现象仍存：婚宴剩菜率超三成，外卖满减活动诱导过量点餐，自助餐“眼大肚子小”造成浪费。市文明办拟面向全体市民发出节约粮食倡议。", "材料二：市文明办工作人员介绍，倡议要讲清浪费的危害、节约的做法，号召市民从自身做起，也要动员身边人，语言要有感染力。", "材料三：市文明办工作人员还介绍，倡议书发布后将通过社区宣传栏、学校课堂、外卖平台弹窗等渠道广泛传播，并联合餐饮协会推出“半份菜”“小份菜”，让节约有抓手。", "材料四：有市民建议，倡议要避免口号化，多给具体可行的做法，比如“点餐先问人数、剩菜主动打包”。市文明办表示将充分吸纳。", "材料五：市文明办还将会同市场监管部门开展“光盘行动进餐厅”活动，对践行节约的餐厅授予流动红旗，营造浪费可耻、节约为荣的社会氛围。有专家表示，移风易俗非一日之功，倡议只是起点，长效机制才是根本，要把节约要求纳入市民公约、村规民约，让节俭成为深入骨髓的习惯。", "节约粮食，功在当代、利在千秋，让我们共同行动起来。"], "question": "假如你是市文明办工作人员，请根据给定资料，以市文明办名义撰写一份节约粮食倡议书。（30分）要求：内容全面，条理清晰，结构完整；不超过450字。", "wordLimit": 450, "scorePoints": [{"point": "标题规范", "synonyms": ["倡议书", "关于节约粮食的倡议书"], "score": 3, "aiOnly": true}, {"point": "称谓与落款格式规范", "synonyms": ["广大市民朋友们", "市文明办", "日期"], "score": 3, "aiOnly": true}, {"point": "指出浪费现象及危害", "synonyms": ["浪费现象", "婚宴剩菜", "粮食安全", "危害"], "score": 6}, {"point": "提出具体节约做法", "synonyms": ["按需点餐", "光盘行动", "剩菜打包", "理性消费"], "score": 9}, {"point": "号召以身作则、带动他人", "synonyms": ["从自身做起", "互相监督", "带动身边人", "宣传引导"], "score": 6}, {"point": "语言有号召力，条理清晰", "synonyms": ["号召", "呼吁", "条理", "感染力"], "score": 3, "aiOnly": true}], "referenceAnswer": "节约粮食倡议书\n\n广大市民朋友们：\n\n一粥一饭，当思来处不易。当前我市餐饮浪费现象仍然存在：婚宴剩菜率超三成，外卖满减诱导过量点餐，自助餐取餐过量。粮食安全是“国之大者”，节约粮食人人有责。为此，我们倡议：\n一、按需点餐，理性消费。外出就餐吃多少点多少，践行“光盘行动”，吃不完主动打包。\n二、抵制诱导，适量取餐。不为满减凑单多点餐，自助餐按量取用、少量多次。\n三、婚丧简办，杜绝铺张。婚宴从简，不讲排场、不比阔气。\n四、以身作则，带动身边人。家长言传身教，单位食堂引导，让节约成为习惯。\n\n节约是美德，更是责任。让我们从现在做起、从每一餐做起，共同守护“舌尖上的文明”！\n\n市文明办\n2022年10月16日", "tips": "命题人提示：倡议书格式分（标题、称谓、落款）由AI判定；内容上按“现象危害—具体做法—号召”展开，做法要具体可操作。"}, {"id": "shl-28", "module": "shenlun", "category": "贯彻执行", "exam": "江苏", "year": 2023, "source": "2023年江苏省考A类第三题（材料改写）", "title": "撰写社区防诈骗宣传活动方案", "material": ["材料一：近期，某社区发生多起针对老年人的电信诈骗案件，有不法分子以“保健品养老”“高息理财”为名骗取老人积蓄。街道办拟在社区开展防诈骗宣传活动。", "材料二：街道工作人员建议，活动要覆盖独居老人等重点人群，形式要让老人听得懂、记得住，比如用身边案例讲解、情景剧表演，还要教会老人使用反诈APP，明确活动时间、地点、分工和保障措施。", "材料三：街道还计划联合派出所、银行网点建立联动机制，发现可疑转账及时劝阻。去年该街道曾成功拦截一起冒充公检法诈骗，为老人挽回损失8万元。", "材料四：工作人员提醒，宣传不能一阵风，要建立常态化机制，让防诈意识真正入脑入心。", "材料五：街道还计划在社区广场设置宣传展板，用漫画形式图解常见骗术；组建由社区民警、律师、社工构成的宣讲团，按月开展巡回宣讲；对独居老人建立结对帮扶台账，志愿者每周电话问候，发现异常及时上门。街道负责人强调，防诈骗宣传既要声势大，更要落点实，让每一位老人都能听得懂、用得上、防得住。"], "question": "假如你是街道办工作人员，请根据给定资料，撰写一份社区防诈骗宣传活动方案。（30分）要求：内容全面，条理清晰，结构完整；不超过450字。", "wordLimit": 450, "scorePoints": [{"point": "标题规范", "synonyms": ["方案", "活动方案", "关于开展防诈骗宣传活动的方案"], "score": 3, "aiOnly": true}, {"point": "明确活动目的与主题", "synonyms": ["目的", "提高防范意识", "主题"], "score": 5}, {"point": "明确时间地点对象", "synonyms": ["时间", "地点", "覆盖独居老人", "重点人群"], "score": 5}, {"point": "活动形式多样具体", "synonyms": ["案例讲解", "情景剧", "反诈APP", "入户宣传"], "score": 8}, {"point": "分工明确责任到人", "synonyms": ["分工", "责任", "组织保障"], "score": 5}, {"point": "保障措施与后续跟进", "synonyms": ["保障", "物资", "后续回访", "总结"], "score": 4}], "referenceAnswer": "社区防诈骗宣传活动方案\n\n为提高老年人防骗意识，守护养老钱袋子，制定本方案。\n一、时间地点：X月15日上午9时，社区广场；同步入户走访独居老人。\n二、宣传对象：社区全体居民，重点是独居老人、子女不在身边的老人。\n三、活动内容：1.民警以“保健品养老”“高息理财”等真实案例讲解骗术套路；2.志愿者表演防诈情景剧，寓教于乐；3.手把手指导安装反诈APP，开启来电预警；4.发放图文宣传册，张贴楼道海报；5.对行动不便老人入户宣讲。\n四、分工保障：综治办统筹协调，民警负责宣讲，志愿者负责组织引导；活动经费由街道保障。\n五、后续跟进：建立重点老人探访台账，每月回访一次，发现可疑情况及时上报。\n\n街道办\nX月10日", "tips": "命题人提示：方案类重在要素齐全——目的、时间地点、对象、内容、分工、保障缺一不可；形式要扣住“让老人听得懂”。"}, {"id": "shl-29", "module": "shenlun", "category": "贯彻执行", "exam": "国考", "year": 2021, "source": "2021年国考副省级第三题（材料改写）", "title": "撰写经验交流发言稿", "material": ["材料一：某区垃圾分类工作连续两年全市考核第一。区里召开经验交流会，要求先进街道发言介绍做法。", "材料二：清河街道的做法是：党员带头包户宣传，桶边督导员定时值守；实行“绿色账户”积分，正确分类可兑换日用品；对物业和保洁员建立奖惩机制；每月公布各小区红黑榜。街道主任将代表街道发言。", "材料三：清河街道的垃圾分类工作并非一帆风顺。起步阶段，居民参与率不足四成，街道没有气馁，通过党员示范、积分激励、红黑榜评比等组合拳，一年后参与率提升至90%以上。", "材料四：街道主任表示，垃圾分类是习惯革命，贵在坚持。下一步将探索智能垃圾桶自动积分，让分类更便捷。", "材料五：街道还注重发挥居民自治作用，各小区成立垃圾分类志愿者队伍，桶边值守从“要我分”变成“我要分”。有居民说：“看着小区干干净净，心里也舒坦。”街道主任表示，垃圾分类没有旁观者，人人都是参与者、受益者，下一步将继续完善设施、优化流程，让分类更简单、更便民，让绿色生活方式在社区蔚然成风。"], "question": "假如你是清河街道主任，请根据给定资料，在经验交流会上作发言介绍垃圾分类的做法。（30分）要求：内容全面，条理清晰，结构完整；不超过450字。", "wordLimit": 450, "scorePoints": [{"point": "称呼与开场规范", "synonyms": ["各位领导", "各位同仁", "发言开场"], "score": 3, "aiOnly": true}, {"point": "总述工作成效", "synonyms": ["考核第一", "成效", "两年"], "score": 4}, {"point": "党员带头宣传发动", "synonyms": ["党员包户", "宣传发动", "党建引领"], "score": 6}, {"point": "桶边督导与积分激励", "synonyms": ["督导员值守", "绿色账户", "积分兑换", "激励"], "score": 8}, {"point": "建立奖惩与红黑榜机制", "synonyms": ["奖惩机制", "红黑榜", "考核评比", "物业责任"], "score": 6}, {"point": "结尾表态或体会", "synonyms": ["体会", "下一步", "表态", "感谢"], "score": 3, "aiOnly": true}], "referenceAnswer": "在全区垃圾分类经验交流会上的发言\n\n各位领导、同仁：\n大家好！很荣幸介绍清河街道的做法。两年来，我街道垃圾分类考核连续全市第一，主要抓了四件事：\n一是党建引领带头分。组织党员包户宣传，挨家挨户讲政策、教方法，让分类意识入脑入心。\n二是桶边值守现场教。聘用督导员早晚高峰定时值守，现场纠正错投行为，手把手养成习惯。\n三是积分激励主动分。推行绿色账户，正确分类积分可兑换日用品，让居民得实惠、有动力。\n四是奖惩分明长效管。明确物业和保洁员责任，建立奖惩机制，每月公布小区红黑榜，比学赶超。\n垃圾分类贵在坚持、重在习惯。我们将继续探索，为全区工作贡献力量。谢谢大家！", "tips": "命题人提示：发言稿要有称呼、开场、正文、结尾；正文做法按“宣传—督导—激励—机制”展开，每条做法配一句成效或意义。"}, {"id": "shl-30", "module": "shenlun", "category": "贯彻执行", "exam": "山东", "year": 2022, "source": "2022年山东省考第三题（材料改写）", "title": "撰写河道治理情况简报", "material": ["材料一：某县开展河道综合治理三个月，累计清理河道垃圾800吨，拆除违建46处，关停非法排污口12个，水质由劣Ⅴ类提升至Ⅳ类。", "材料二：县河长办拟将治理情况编发简报，报送县领导并印发各乡镇。简报要突出做法、成效和下一步安排，语言简明扼要。", "材料三：治理期间，县里实行周调度、月通报，乡镇之间互查互评。有乡镇因清理不及时被通报批评，连夜组织整改。", "材料四：下一步，县里计划聘请专业保洁公司实行河道日常保洁，实现从“运动式治理”向“常态化管护”转变。", "材料五：县里还同步推进生态修复工程，在河道两岸种植水生植物，投放鱼苗，逐步恢复水体自净能力。沿河群众说：“水清了，鱼回来了，小时候的河又回来了。”县河长办表示，河道治理三分治、七分管，将建立日常巡查、问题交办、整改销号闭环机制，确保治理成果长效保持，让每条河流都成为造福人民的幸福河。", "县里还将开展“清河行动”回头看，防止问题反弹回潮。"], "question": "假如你是县河长办工作人员，请根据给定资料，撰写一份河道治理情况简报。（30分）要求：内容全面，条理清晰，结构完整；不超过400字。", "wordLimit": 400, "scorePoints": [{"point": "标题规范", "synonyms": ["简报", "工作简报", "河道治理简报"], "score": 3, "aiOnly": true}, {"point": "概述治理背景与总体情况", "synonyms": ["背景", "总体情况", "开展治理"], "score": 5}, {"point": "列举主要做法", "synonyms": ["清理垃圾", "拆除违建", "关停排污口", "综合整治"], "score": 8}, {"point": "量化治理成效", "synonyms": ["800吨", "46处", "水质提升"], "score": 7}, {"point": "提出下一步安排", "synonyms": ["下一步", "长效机制", "继续推进", "巩固成果"], "score": 5}, {"point": "语言简明，格式规范", "synonyms": ["简明扼要", "报头", "报送范围"], "score": 2, "aiOnly": true}], "referenceAnswer": "河道治理工作简报\n\n（第5期）\n县河长办编印  X月X日\n\n我县自X月开展河道综合治理以来，坚持问题导向、标本兼治，取得阶段性成效。现将有关情况通报如下：\n一、主要做法。组织沿河乡镇集中清理河道垃圾800吨；依法拆除沿河违建46处；排查关停非法排污口12个，从源头截断污染。\n二、治理成效。全县主要河道水质由劣Ⅴ类提升至Ⅳ类，河道面貌明显改观，群众满意度显著提高。\n三、下一步安排。一是建立日常保洁长效机制，落实专人管护；二是加强巡查执法，严防问题反弹；三是推进生态修复，逐步恢复河道自净能力。\n\n报：县委、县政府领导\n发：各乡镇人民政府", "tips": "命题人提示：简报要有报头（期号、编印单位、日期）和报送范围；正文按“做法—成效—下一步”三段式，成效必须用数据说话。"}, {"id": "shl-31", "module": "shenlun", "category": "贯彻执行", "exam": "国考", "year": 2023, "source": "2023年国考副省级第三题（材料改写）", "title": "撰写博物馆参观须知（宣传稿）", "material": ["材料一：某市博物馆免费开放后客流激增，出现大声喧哗、触摸展品、开闪光灯拍照、儿童追逐打闹等现象，影响参观体验和文物安全。", "材料二：馆方拟发布参观须知，引导文明参观。工作人员提示，须知要明确开放时间、预约方式，重点提示禁止行为及理由，语气要友善得体。", "材料三：馆方还介绍，博物馆将增设语音导览和休息区，为观众提供更好体验。针对节假日客流高峰，实行分时段预约，避免扎堆。", "材料四：有观众表示，文明参观需要大家共同维护，看到不文明行为也会善意提醒。", "材料五：馆方还提醒，大件行李需寄存，宠物不得入馆；展厅内禁止使用自拍杆和三脚架，以免影响他人参观和文物安全。博物馆是公共文化空间，文明是最美的风景。馆方表示，将不断优化服务措施，同时欢迎观众通过意见簿、公众号留言等方式提出建议，共同营造安全、有序、舒适的参观环境，让每一次参观都成为美好的文化之旅。", "馆方将定期发布参观提示，引导观众错峰参观、文明观展。"], "question": "假如你是博物馆工作人员，请根据给定资料，撰写一份参观须知。（30分）要求：内容全面，条理清晰，结构完整；不超过400字。", "wordLimit": 400, "scorePoints": [{"point": "标题规范", "synonyms": ["参观须知", "参观须知标题"], "score": 3, "aiOnly": true}, {"point": "开放时间与预约方式", "synonyms": ["开放时间", "预约", "免费开放", "入馆方式"], "score": 6}, {"point": "文明观展提示", "synonyms": ["轻声细语", "不喧哗", "有序参观", "文明"], "score": 6}, {"point": "文物保护禁止行为", "synonyms": ["禁止触摸", "禁用闪光灯", "文物安全", "禁止饮食"], "score": 7}, {"point": "儿童看护与安全提示", "synonyms": ["看护儿童", "安全", "禁止追逐打闹"], "score": 5}, {"point": "语气友善得体", "synonyms": ["感谢配合", "欢迎", "友善"], "score": 3, "aiOnly": true}], "referenceAnswer": "参观须知\n\n欢迎参观市博物馆！为营造良好参观环境，请留意以下事项：\n一、开放信息。本馆免费开放，开放时间为周二至周日9:00—17:00（16:30停止入馆），周一闭馆。请提前通过官方公众号实名预约，凭码入馆。\n二、文明观展。请保持安静，轻声交流，勿喧哗奔跑；自觉排队，有序参观。\n三、爱护文物。展厅内请勿触摸展品、展柜；拍照请关闭闪光灯，闪光灯会加速文物老化；请勿携带食品饮料入馆。\n四、看护儿童。请家长照看好随行儿童，勿让其在展厅追逐打闹。\n感谢您的理解与配合，祝您参观愉快！", "tips": "命题人提示：须知类文体重提示性，每条禁止行为最好附上理由（如闪光灯加速文物老化），语气友善不生硬。"}, {"id": "shl-32", "module": "shenlun", "category": "贯彻执行", "exam": "江苏", "year": 2022, "source": "2022年江苏省考B类第三题（材料改写）", "title": "撰写乡村民宿发展调研报告提纲", "material": ["材料一：某区政协组织委员调研乡村民宿发展情况。调研发现：全区民宿120家，其中精品民宿仅15家；多数民宿同质化经营，淡季入住率不足三成；消防、卫生等证照办理渠道不畅；从业人员多为本地村民，缺乏专业运营人才。", "材料二：委员们建议编制调研报告，内容包括基本情况、存在问题、原因分析和对策建议，要求问题找准、建议可行。", "材料三：调研组还走访了江浙民宿发达地区，学习先进经验。委员们发现，当地通过民宿协会统一标准、统一营销，避免了恶性竞争，值得借鉴。", "材料四：区政协将把调研报告提交区委区政府，为决策提供参考。", "材料五：调研还发现，部分民宿业主反映融资难，扩大经营缺乏资金支持；一些村庄基础设施薄弱，通往民宿的道路狭窄，旅游大巴无法通行。委员们建议，将民宿发展纳入乡村振兴整体规划，统筹推进道路、停车场、污水处理等配套设施建设；鼓励金融机构开发民宿贷等专属产品，为民宿发展注入金融活水，让民宿经济成为富民强村的新引擎。"], "question": "假如你是区政协工作人员，请根据给定资料，撰写乡村民宿发展情况调研报告的提纲。（30分）要求：内容全面，条理清晰，结构完整；不超过400字。", "wordLimit": 400, "scorePoints": [{"point": "标题规范", "synonyms": ["调研报告", "关于乡村民宿发展情况的调研报告"], "score": 3, "aiOnly": true}, {"point": "基本情况部分", "synonyms": ["120家", "精品15家", "发展现状", "基本情况"], "score": 6}, {"point": "存在问题部分", "synonyms": ["同质化", "入住率低", "证照难办", "人才缺乏"], "score": 9}, {"point": "原因分析部分", "synonyms": ["原因", "经营理念", "政策渠道", "要素制约"], "score": 6}, {"point": "对策建议部分", "synonyms": ["差异化", "培训人才", "简化审批", "政策支持"], "score": 6}], "referenceAnswer": "关于全区乡村民宿发展情况的调研报告（提纲）\n\n一、基本情况。全区现有民宿120家，其中精品民宿15家；民宿经济初具规模，但发展质量有待提升。\n二、存在问题。1.同质化经营普遍，特色不足；2.淡季入住率不足三成，经营效益差；3.消防、卫生等证照办理渠道不畅；4.从业人员以本地村民为主，专业运营人才缺乏。\n三、原因分析。1.经营理念落后，缺乏品牌意识；2.政策配套不足，审批路径不明确；3.人才培养引进机制缺失。\n四、对策建议。1.引导差异化、精品化发展，打造区域民宿品牌；2.建立证照办理联审联批机制；3.开展从业人员培训，引进专业运营团队；4.策划四季旅游产品，破解淡季难题。", "tips": "命题人提示：提纲类不展开成文，按“情况—问题—原因—建议”列要点即可；问题要照应材料数据，建议要与问题一一对应。"}, {"id": "shl-33", "module": "shenlun", "category": "贯彻执行", "exam": "国考", "year": 2020, "source": "2020年国考市地级第三题（材料改写）", "title": "撰写易地搬迁后续扶持工作情况汇报", "material": ["材料一：某乡完成易地扶贫搬迁，326户群众迁入新社区。乡里配套建设扶贫车间，引进服装加工企业，安排就业180人；开发公益性岗位32个，安置弱劳动力；组织技能培训12期，培训600人次。", "材料二：但仍有部分群众不适应社区生活，存在楼上养鸡、楼道堆物等现象；社区党组织刚组建，服务力量薄弱。乡党委拟向县里汇报后续扶持情况。", "材料三：搬迁群众老张说：“以前在山上，孩子上学要走两小时山路；现在楼下就是学校，心里踏实了。”社区还建起扶贫车间，让留守妇女在家门口就业。", "材料四：乡党委表示，搬迁只是第一步，让群众融入新生活、过上好日子，才是后续扶持的落脚点。", "材料五：社区还开展“邻里守望”活动，组织搬迁群众互帮互助，尽快熟悉新环境；开办社区讲堂，讲授城市生活常识，从垃圾分类到乘坐电梯，帮助群众完成从村民到居民的身份转变。乡党委负责人表示，易地搬迁是手段，脱贫致富是目的，后续扶持将聚焦就业、融入、服务三个关键，确保群众搬得出、稳得住、逐步能致富。"], "question": "假如你是乡党委工作人员，请根据给定资料，撰写一份易地搬迁后续扶持工作情况汇报。（30分）要求：内容全面，条理清晰，结构完整；不超过450字。", "wordLimit": 450, "scorePoints": [{"point": "标题规范", "synonyms": ["汇报", "情况汇报", "关于易地搬迁后续扶持工作情况的汇报"], "score": 3, "aiOnly": true}, {"point": "概述搬迁基本情况", "synonyms": ["326户", "迁入新社区", "基本情况"], "score": 5}, {"point": "就业扶持做法与成效", "synonyms": ["扶贫车间", "公益性岗位", "技能培训", "就业180人"], "score": 9}, {"point": "存在问题不回避", "synonyms": ["不适应", "楼上养鸡", "楼道堆物", "党组织薄弱"], "score": 7}, {"point": "下一步工作打算", "synonyms": ["融入引导", "建强党组织", "社区服务", "下一步"], "score": 6}], "referenceAnswer": "关于易地搬迁后续扶持工作情况的汇报\n\n县委：\n我乡易地扶贫搬迁326户已全部迁入新社区。现将后续扶持情况汇报如下：\n一、就业帮扶稳收入。建设扶贫车间引进服装企业，安排就业180人；开发保洁、治安等公益性岗位32个，安置弱劳动力；组织技能培训12期600人次，确保户户有增收门路。\n二、存在问题须重视。部分群众生活习惯未转变，存在楼上养鸡、楼道堆物等现象；社区党组织刚组建，服务力量薄弱。\n三、下一步打算。一是开展文明新风宣传，修订社区公约，引导群众融入新生活；二是加快建强社区党组织，配齐网格员和楼栋长；三是完善物业、养老等服务设施，让群众搬得出、稳得住、能致富。\n\n以上汇报，请指示。\n\n乡党委\nX年X月X日", "tips": "命题人提示：汇报要如实反映问题，不回避矛盾；结构按“成效—问题—打算”，落款用乡党委名义。"}, {"id": "shl-34", "module": "shenlun", "category": "贯彻执行", "exam": "浙江", "year": 2023, "source": "2023年浙江省考第三题（材料改写）", "title": "撰写全民健身场地建设建议书", "material": ["材料一：某市调查发现，全市人均体育场地面积1.8平方米，低于国家标准；老旧小区健身器材老化，公园绿道缺乏健身设施；“健身去哪儿”成为群众反映强烈的问题。", "材料二：市人大代表建议：利用金角银边建设口袋健身广场；学校体育场馆错时开放；新建小区按标准配建健身设施；发动社会力量参与运营。人大拟向市政府提交建议书。", "材料三：有市民建议，健身场地建设要倾听群众声音，建到哪里、建成什么样，让群众说了算。还有市民希望增加夜间照明，方便下班后锻炼。", "材料四：市人大常委会表示，将把建议梳理后转交市政府研究办理，并跟踪督办落实情况。", "材料五：市人大代表还建议，将全民健身场地建设纳入城市体检指标，每年向社会公布建设进展；对已建成的健身设施定期巡检维护，确保正常使用。有专家指出，全民健身是实现全民健康的重要途径，场地设施是基础支撑，政府、社会、市场应协同发力，让健身设施像便利店一样随处可见，让运动融入市民日常生活。", "市人大常委会将持续跟踪建议办理情况，推动问题解决。"], "question": "假如你是市人大常委会工作人员，请根据给定资料，撰写一份关于加强全民健身场地建设的建议书。（30分）要求：内容全面，条理清晰，结构完整；不超过400字。", "wordLimit": 400, "scorePoints": [{"point": "标题规范", "synonyms": ["建议书", "关于加强全民健身场地建设的建议书"], "score": 3, "aiOnly": true}, {"point": "说明现状与问题", "synonyms": ["人均1.8平方米", "器材老化", "健身去哪儿", "低于标准"], "score": 7}, {"point": "建议利用边角地建场地", "synonyms": ["金角银边", "口袋健身广场", "盘活空间"], "score": 6}, {"point": "建议学校场馆开放", "synonyms": ["错时开放", "学校场馆", "资源共享"], "score": 5}, {"point": "建议配建与运营机制", "synonyms": ["新建小区配建", "社会力量", "运营机制"], "score": 6}, {"point": "结尾表达期望", "synonyms": ["希望", "采纳", "落实"], "score": 3, "aiOnly": true}], "referenceAnswer": "关于加强全民健身场地建设的建议书\n\n市人民政府：\n近年来，我市“健身去哪儿”问题突出：人均体育场地面积1.8平方米，低于国家标准；老旧小区器材老化，公园绿道健身设施缺乏。为满足群众健身需求，建议：\n一、盘活城市空间。利用城市“金角银边”，建设口袋健身广场，让群众家门口就能锻炼。\n二、推动场馆共享。学校体育场馆课余时间错时向社会开放，明确管理责任和安全保障。\n三、严格配建标准。新建小区按人均标准同步配建健身设施，老旧小区改造时更新器材。\n四、创新运营机制。发动社会力量参与建设运营，探索低免收费模式，实现可持续。\n\n以上建议，望研究采纳，并切实推动落实。\n\n市人大常委会\nX年X月X日", "tips": "命题人提示：建议书要“摆问题+提建议”，问题用数据支撑；建议分条对应问题，落款为市人大常委会。"}, {"id": "shl-35", "module": "shenlun", "category": "贯彻执行", "exam": "江苏", "year": 2024, "source": "2024年江苏省考A类第三题（材料改写）", "title": "撰写人才回引公开信", "material": ["材料一：某县为振兴乡村，拟向在外务工经商人员发出公开信，回引人才返乡创业。县里梳理了返乡创业扶持政策：创业担保贷款最高30万元、税费减免、免费场地三年、子女入学便利等。", "材料二：县里还整理了一批返乡创业典型：有人回乡办家庭农场年入百万，有人开办电商公司带动全村卖山货。公开信要求情真意切，既讲政策，也讲乡情。", "材料三：县里还建立了在外人才信息库，节日期间通过座谈会、上门走访等方式联络乡情。不少在外人才表示，家乡的政策和服务让人暖心。", "材料四：县委主要负责人说：“引回来只是开始，扶上马、送一程，让人才留得住、干得好，才是我们的目标。”", "材料五：县里还推出“返乡创业一件事”集成服务，创业登记、贷款申请、场地对接一窗受理；建立县领导联系返乡人才制度，每人结对联系5名在外人才，定期沟通、及时解难。县委主要负责人表示，人才是乡村振兴的第一资源，要以最大诚意、最优政策、最好服务，让在外人才感受到家乡的呼唤与温度，让更多“归雁”成为乡村振兴的领头雁。"], "question": "假如你是县委组织部工作人员，请根据给定资料，以县委县政府名义撰写一封致在外人才的公开信。（30分）要求：内容全面，条理清晰，结构完整；不超过450字。", "wordLimit": 450, "scorePoints": [{"point": "标题规范", "synonyms": ["公开信", "致在外人才的一封信"], "score": 3, "aiOnly": true}, {"point": "称谓与问候得体", "synonyms": ["在外务工经商的乡亲们", "问候", "乡情"], "score": 3, "aiOnly": true}, {"point": "介绍家乡发展变化与机遇", "synonyms": ["家乡变化", "发展机遇", "乡村振兴"], "score": 7}, {"point": "列举创业扶持政策", "synonyms": ["贷款30万", "税费减免", "免费场地", "子女入学"], "score": 8}, {"point": "列举返乡创业典型", "synonyms": ["家庭农场", "电商公司", "典型带动"], "score": 4}, {"point": "发出诚挚邀请", "synonyms": ["返乡创业", "共建家乡", "诚挚邀请"], "score": 5}], "referenceAnswer": "致在外人才的一封信\n\n在外务工经商的乡亲们：\n你们好！多年来，你们在外打拼，用勤劳撑起了家庭，也练就了本领。家乡的发展离不开你们，乡村振兴的舞台正盼着你们！\n如今的家乡，道路畅了、环境美了、产业兴了，处处是机遇。县委县政府为返乡创业准备了“政策礼包”：创业担保贷款最高30万元，税费依法减免，免费提供经营场地三年，子女入学优先安排。\n乡亲们，身边榜样最有说服力：李明回乡办家庭农场，年入上百万元；王芳开电商公司，带动全村山货卖向全国。他们能行，你们也一定能行！\n家乡的水还是那样甜，家乡的门永远为你们敞开。诚邀大家返乡创业、共建家园，让人生出彩，让家乡变样！\n\n中共某县委 某县人民政府\nX年X月X日", "tips": "命题人提示：公开信要动之以情、晓之以策；政策要点须逐项列明，典型事例增强感染力，结尾发出邀请。"}, {"id": "shl-36", "module": "shenlun", "category": "贯彻执行", "exam": "国考", "year": 2024, "source": "2024年国考副省级第三题（材料改写）", "title": "撰写优化政务服务编者按", "material": ["材料一：某报开设“优化政务服务进行时”专栏，首期刊发三篇报道：A市推行“一网通办”让数据多跑路；B县“办不成事”窗口专治疑难杂症；C区帮办代办队伍服务特殊群体。", "材料二：编辑部拟为专栏配发编者按，说明开设背景、专栏宗旨和报道内容概要，引导读者关注和参与讨论。", "材料三：专栏还将开设互动话题，邀请读者分享办事经历，对好做法点赞、对堵点问题吐槽。编辑部表示，舆论监督是优化政务服务的重要力量。", "材料四：首期报道刊发后，读者反响热烈，纷纷留言讲述自己的办事体验，为栏目提供了丰富线索。", "材料五：编辑部还介绍，专栏将不定期刊发评论员文章，对各地探索进行点评；开设“政务服务金点子”征集活动，优秀建议将转交有关部门研究吸纳。有专家表示，政务服务改革永远在路上，媒体既要当好宣传员，也要当好监督员，让好经验传得开、堵点问题改得快，推动政务服务从“能办”向“好办”转变。", "编辑部欢迎广大读者踊跃投稿，共同讲好政务服务故事。"], "question": "假如你是报社编辑，请根据给定资料，为“优化政务服务进行时”专栏撰写编者按。（30分）要求：内容全面，条理清晰，结构完整；不超过350字。", "wordLimit": 350, "scorePoints": [{"point": "点明开设背景与宗旨", "synonyms": ["背景", "宗旨", "深化放管服", "群众需求"], "score": 9}, {"point": "概括三篇报道内容", "synonyms": ["一网通办", "办不成事窗口", "帮办代办", "三篇报道"], "score": 11}, {"point": "发出关注与参与号召", "synonyms": ["关注", "参与讨论", "建言献策", "期待"], "score": 7}, {"point": "语言精炼，体例规范", "synonyms": ["编者按", "精炼", "按语"], "score": 3, "aiOnly": true}], "referenceAnswer": "编者按\n\n政务服务一头连着政府，一头连着群众。深化“放管服”改革、优化政务服务，是提升群众获得感的关键之举。自今日起，本报开设“优化政务服务进行时”专栏，聚焦各地探索，传递基层声音。\n首期刊发三篇报道：A市推行“一网通办”，让数据多跑路、群众少跑腿；B县设立“办不成事”反映窗口，专解群众办事疑难；C区组建帮办代办队伍，为老年人等特殊群体送上贴心服务。三地做法各有侧重，共同指向一个目标——把服务做到群众心坎上。\n优化政务服务没有完成时。欢迎广大读者关注专栏、建言献策，共同推动政务服务再上新台阶。", "tips": "命题人提示：编者按短小精悍，须交代背景宗旨、概括内容、发出号召三部分；概括报道要抓住各地做法的关键词。"}, {"id": "shl-37", "module": "shenlun", "category": "文章写作", "exam": "国考", "year": 2022, "source": "2022年国考副省级第五题（主题改写）", "title": "以“治慧”为话题写文章", "material": ["材料一：某市治理交通拥堵，不是简单限行，而是优化公交线路、错峰上下学、建设智慧停车系统，堵点逐一化解。", "材料二：治理如中医看病，讲究望闻问切、辨证施治。同样是治理城市，有的城市大拆大建，越治越乱；有的城市绣花功夫，越治越顺。", "材料三：老子说：“治大国若烹小鲜。”治理需要智慧，需要把握火候、拿捏分寸。", "材料四：某市推行“街乡吹哨、部门报到”机制，基层发现问题、部门限时解决，治理效能明显提升。", "材料五：也有城市探索“市民圆桌会”，把治理难题摆到桌面上，让市民与部门面对面协商，很多矛盾化解在萌芽状态。专家指出，治理智慧的最高境界，是让城市成为共建共治共享的命运共同体。", "材料六：从网格化管理到智慧城市大脑，从“最多跑一次”到“无证明城市”，各地治理创新层出不穷。实践证明，治理智慧源于对规律的把握、对民意的尊重和对细节的执着，唯有把功夫下在平时、把心思用在实处，治理才能既有力度又有温度。"], "question": "给定资料中提到“治理需要智慧”。请结合你对这句话的理解，自拟题目，写一篇文章。（50分）要求：观点明确，论证充分，条理清晰，语言流畅；1000~1200字。", "wordLimit": 1200, "scorePoints": [{"point": "标题切合主题", "synonyms": ["治慧", "治理智慧", "治理需要智慧"], "score": 5, "aiOnly": true}, {"point": "立意准确，紧扣治理智慧", "synonyms": ["辨证施治", "把握火候", "绣花功夫", "因城施策"], "score": 12, "aiOnly": true}, {"point": "结构完整，分论点清晰", "synonyms": ["首先", "其次", "一方面", "总—分—总"], "score": 10, "aiOnly": true}, {"point": "论证充分，例证结合材料内外", "synonyms": ["某市交通", "大拆大建", "举例", "事实论证"], "score": 13, "aiOnly": true}, {"point": "语言规范流畅", "synonyms": ["流畅", "规范", "文采"], "score": 10, "aiOnly": true}], "referenceAnswer": "治理之要 唯在得“慧”\n\n城市治理千头万绪，有的城市大拆大建，按下葫芦浮起瓢；有的城市用绣花功夫，堵点逐一化解。同样的资源，不同的结果，差别就在一个“慧”字。治理之要，唯在得慧。\n治理智慧，在于辨证施治、找准病根。中医看病讲究望闻问切，城市治理同样要找准症结。某市治理交通拥堵，没有一限了之，而是优化公交、错峰上下学、建设智慧停车系统，多管齐下，堵点自然化解。倘若只看表面头痛医头，不问病根，治理只会陷入“越治越堵”的怪圈。\n治理智慧，在于把握火候、拿捏分寸。治大国若烹小鲜，火候不到则夹生，火候过猛则烧焦。治理既要避免不作为的“冷”，也要防止乱作为的“急”。政策出台前充分论证，执行中留有弹性，给市场和社会自我调节的空间，方能行稳致远。\n治理智慧，在于下绣花功夫、久久为功。城市的核心是人，治理的落点在民生细节。盲道是否畅通、公厕是否好找，看似小事，却考验治理的精细度。绣花功夫不是一日之功，需要一张蓝图绘到底，一茬接着一茬干。\n治理有慧，则城市有温度、发展有质量。广大干部当以辨证思维察实情，以分寸感把火候，以绣花功抓细节，让治理更有智慧，让生活更加美好。", "tips": "命题人提示：围绕“治理智慧”立意，可从辨证施治、把握火候、绣花功夫三个分论点展开，材料中的正反事例是现成论据。"}, {"id": "shl-38", "module": "shenlun", "category": "文章写作", "exam": "江苏", "year": 2023, "source": "2023年江苏省考A类第五题（主题改写）", "title": "以“创新”为主题写文章", "material": ["材料一：江苏某企业三十年专注一片薄膜，从农膜到光伏膜再到柔性显示材料，靠持续创新成为行业隐形冠军。", "材料二：有人认为创新是科学家的事，与普通人无关；也有人说，创新就是把不可能变成可能，人人皆可创新。", "材料三：从“神舟”飞天到“蛟龙”入海，从北斗组网到高铁飞驰，创新是引领发展的第一动力。", "材料四：某市出台政策，允许科研人员离岗创业、在岗兼职，职务发明收益七成归团队，激发了创新热情。", "材料五：一位青年创客说：“创新不怕失败，怕的是没有试错的机会。”该市还设立创新容错基金，为敢于冒险的团队兜底。专家指出，创新的种子需要制度的土壤，好的生态能让创新之花竞相绽放。", "材料六：从实验室到生产线，从论文到产品，创新的价值最终要靠实践检验。某科研团队十年攻关，把一项关键技术从图纸变成现实，打破了国外垄断。团队负责人说：“创新没有捷径，唯有把冷板凳坐热，把硬骨头啃下。”这启示我们，创新既要有仰望星空的想象力，也要有脚踏实地的执行力。"], "question": "请结合给定资料，围绕“创新”这一主题，自拟题目，写一篇文章。（50分）要求：观点明确，论证充分，条理清晰，语言流畅；1000~1200字。", "wordLimit": 1200, "scorePoints": [{"point": "标题切合创新主题", "synonyms": ["创新", "创新驱动", "第一动力"], "score": 5, "aiOnly": true}, {"point": "立意准确，突出创新是发展第一动力", "synonyms": ["第一动力", "引领发展", "创新驱动发展"], "score": 12, "aiOnly": true}, {"point": "结构完整，分论点清晰", "synonyms": ["首先", "其次", "分论点", "层次"], "score": 10, "aiOnly": true}, {"point": "论证充分，例证丰富", "synonyms": ["薄膜企业", "神舟", "北斗", "举例"], "score": 13, "aiOnly": true}, {"point": "语言规范流畅", "synonyms": ["流畅", "规范", "文采"], "score": 10, "aiOnly": true}], "referenceAnswer": "让创新成为发展第一动力\n\n从“神舟”飞天到“蛟龙”入海，从北斗组网到高铁飞驰，一项项大国重器的背后，是创新这个共同的名字。江苏某企业三十年专注一片薄膜，从农膜做到柔性显示材料，靠持续创新成为隐形冠军。事实一再证明：创新是引领发展的第一动力。\n创新，要有十年磨一剑的定力。创新不是灵光一现，而是长期积累的厚积薄发。一片薄膜钻研三十年，靠的是耐得住寂寞的专注。当前一些企业热衷赚快钱，追风口、蹭热点，最终昙花一现。唯有像薄膜企业那样心无旁骛攻主业，方能在细分领域做到极致。\n创新，要让人人皆可创新。创新不只是实验室里的科学家的事。生产线上改进一道工序，窗口服务优化一个流程，田间地头改良一项技术，都是创新。把创新的门槛降下来，让一线工人的“金点子”变成生产力，创新的源泉才会充分涌流。\n创新，要有宽容失败的生态。创新之路没有坦途，失败是常态。倘若一次失败就全盘否定，谁还敢闯敢试？要建立容错机制，让敢创新者无后顾之忧，让真创新者得真回报。\n惟创新者进，惟创新者强，惟创新者胜。站在新的历史起点，我们当以定力深耕主业，以众智激发活力，以生态护航远航，让创新之火燃成发展之焰，为高质量发展注入不竭动力。", "tips": "命题人提示：创新主题要避免空喊口号，可从“定力—人人创新—生态”三个层面立论，材料中薄膜企业和大国重器都是好论据。"}, {"id": "shl-39", "module": "shenlun", "category": "文章写作", "exam": "国考", "year": 2023, "source": "2023年国考市地级第五题（主题改写）", "title": "以“奋斗”为主题写文章", "material": ["材料一：塞罕坝三代人接力造林，把荒漠变成林海；黄文秀放弃城市工作回乡扶贫，把生命定格在扶贫路上。", "材料二：有人说，奋斗是艰辛的，但幸福都是奋斗出来的；也有人说，躺平虽轻松，却会让人生失去重量。", "材料三：新时代是奋斗者的时代。", "材料四：某村第一书记扎根五年，带领村民修路、引水、发展产业，村里变了样，他的头发也白了半边。村民说：“他把心掏给我们，我们跟着他有奔头。”", "材料五：也有青年在网络上感慨“内卷”“躺平”，引发热议。专家指出，奋斗不是盲目内卷，躺平也不是人生答案，关键在于找到值得奋斗的方向，在奋斗中实现自我价值与社会价值的统一。", "材料六：从“两弹一星”到载人航天，从脱贫攻坚到乡村振兴，一代代奋斗者接续拼搏，铸就了今日之中国。历史由奋斗者书写，未来靠奋斗者开创。新征程上，机遇与挑战并存，唯有保持奋斗姿态，才能在时代大潮中勇立潮头，让人生在奋斗中升华，让梦想在实干中成真。"], "question": "请结合给定资料，围绕“奋斗”这一主题，自拟题目，写一篇文章。（50分）要求：观点明确，论证充分，条理清晰，语言流畅；1000~1200字。", "wordLimit": 1200, "scorePoints": [{"point": "标题切合奋斗主题", "synonyms": ["奋斗", "奋斗者", "幸福都是奋斗出来的"], "score": 5, "aiOnly": true}, {"point": "立意准确，突出奋斗成就幸福", "synonyms": ["幸福都是奋斗出来的", "奋斗成就人生", "接续奋斗"], "score": 12, "aiOnly": true}, {"point": "结构完整，分论点清晰", "synonyms": ["首先", "其次", "分论点", "层次"], "score": 10, "aiOnly": true}, {"point": "论证充分，例证丰富", "synonyms": ["塞罕坝", "黄文秀", "举例", "事实论证"], "score": 13, "aiOnly": true}, {"point": "语言规范流畅", "synonyms": ["流畅", "规范", "文采"], "score": 10, "aiOnly": true}], "referenceAnswer": "以奋斗之笔 书写幸福答卷\n\n塞罕坝三代人接力造林，让荒漠变林海；黄文秀把生命定格在扶贫路上，用青春兑现誓言。他们的人生轨迹不同，精神底色相同——奋斗。幸福都是奋斗出来的，新时代是奋斗者的时代。\n奋斗，是改变命运的钥匙。贫困不是宿命，躺平等不来小康。从脱贫攻坚到乡村振兴，千千万万群众靠双手奋斗出好日子。事实告诉我们：等靠要换不来幸福，撸起袖子加油干才有出路。\n奋斗，是成就事业的阶梯。任何伟大事业都是干出来的。塞罕坝人一锹一穴种出百万亩林海，靠的是一代接着一代干的韧劲。反观有些人遇事只想“躺平”，看似轻松，实则让人生失去重量。青春由磨砺而出彩，人生因奋斗而升华。\n奋斗，要讲科学方法、久久为功。奋斗不是蛮干。塞罕坝人总结规律、科学造林，才让树苗成活；扶贫干部精准施策，才让帮扶见效。奋斗还要有接力意识，一张蓝图绘到底，不贪一时之功、不图一时之名。\n征途漫漫，惟有奋斗。站在新的起点，我们当以奋斗者的姿态迎难而上，把个人奋斗融入时代洪流，用汗水浇灌收获，以实干笃定前行，让人生在奋斗中绽放光彩。", "tips": "命题人提示：奋斗主题立意要落到“幸福都是奋斗出来的”，可用塞罕坝、黄文秀正面论证，用“躺平”作反面对照。"}, {"id": "shl-40", "module": "shenlun", "category": "文章写作", "exam": "浙江", "year": 2022, "source": "2022年浙江省考第五题（主题改写）", "title": "以“绿水青山就是金山银山”为主题写文章", "material": ["材料一：浙江安吉余村，关停矿山后发展生态旅游，村民人均收入翻了几番，村口石碑上刻着“绿水青山就是金山银山”。", "材料二：有的地方仍走老路，先污染后治理，代价沉重；有的地方守着绿水青山受穷，不知转化之道。", "材料三：生态本身就是经济，保护生态就是发展生产力。", "材料四：某地依托好山好水发展康养产业，吸引大批城市老人旅居养老，绿水青山变成了养老院里的欢声笑语。", "材料五：也有村庄守着青山绿水却不知如何变现，年轻人外流，村庄空心化。专家指出，生态优势不会自动变成经济优势，需要找准转化路径：或发展生态旅游，或培育绿色农业，或吸引环境友好型产业，让绿水青山持续释放红利。", "材料六：从“沙逼人退”到“人进沙退”，从荒山秃岭到层林尽染，一代代生态建设者用汗水浇灌绿色梦想。实践证明，生态环境保护和经济发展不是矛盾对立的关系，而是辩证统一的关系。把生态优势转化为发展优势，把绿水青山打造成金山银山，人与自然和谐共生的现代化道路必将越走越宽广。"], "question": "请结合给定资料，围绕“绿水青山就是金山银山”这一主题，自拟题目，写一篇文章。（50分）要求：观点明确，论证充分，条理清晰，语言流畅；1000~1200字。", "wordLimit": 1200, "scorePoints": [{"point": "标题切合两山主题", "synonyms": ["绿水青山", "金山银山", "两山"], "score": 5, "aiOnly": true}, {"point": "立意准确，突出生态与发展的辩证统一", "synonyms": ["生态就是经济", "转化", "辩证统一", "保护生产力"], "score": 12, "aiOnly": true}, {"point": "结构完整，分论点清晰", "synonyms": ["首先", "其次", "分论点", "层次"], "score": 10, "aiOnly": true}, {"point": "论证充分，正反结合", "synonyms": ["余村", "先污染后治理", "守着青山受穷", "举例"], "score": 13, "aiOnly": true}, {"point": "语言规范流畅", "synonyms": ["流畅", "规范", "文采"], "score": 10, "aiOnly": true}], "referenceAnswer": "让绿水青山源源不断带来金山银山\n\n浙江余村，曾靠开山采矿富了口袋、毁了环境；关停矿山后，依托绿水青山发展生态旅游，村民收入不降反升。村口石碑上的“绿水青山就是金山银山”，正是这条转化之路的生动注脚。\n绿水青山是本钱，守护生态就是守护发展根基。有的地方仍走先污染后治理的老路，账面富了、环境毁了，治理代价远超收益。生态一旦破坏，金山银山也买不回蓝天碧水。因此，发展决不能以牺牲环境为代价，守住生态底线，才有发展的本钱。\n绿水青山要变现，关键在打通转化通道。守着青山受穷，是因为缺少转化的桥梁。余村把生态优势变成旅游优势，有的地方把好山好水变成农产品品牌，有的地方靠好生态吸引绿色产业。实践证明，生态本身就是经济，只要找准路径，绿水青山就能源源不断带来金山银山。\n转化要有制度护航，让保护者不吃亏。生态补偿、绿色金融、排污权交易等制度，让保护生态者得实惠。唯有让制度激励与市场机制同向发力，绿色发展才能行稳致远。\n人不负青山，青山定不负人。让我们坚定走生态优先、绿色发展之路，把生态优势转化为发展优势，让绿水青山永续，让金山银山常在。", "tips": "命题人提示：两山主题重在“转化”二字，立意要体现生态与发展的辩证统一；余村是正面典型，先污染后治理是反面教训。"}, {"id": "shl-41", "module": "shenlun", "category": "文章写作", "exam": "江苏", "year": 2022, "source": "2022年江苏省考A类第五题（主题改写）", "title": "以“文化自信”为主题写文章", "material": ["材料一：故宫文创年销售额超15亿元，让600岁的故宫“活”了起来；《只此青绿》舞出千里江山，一票难求。", "材料二：也有人对传统文化缺乏了解，过洋节热闹过传统节冷清；有人把传统简单等同于落后。", "材料三：文化是一个国家、一个民族的灵魂。文化兴国运兴，文化强民族强。", "材料四：某地举办汉服节，万人空巷；博物馆夜游一票难求，年轻人排队打卡。传统文化正以时尚方式回归日常生活。", "材料五：也有学者提醒，文化自信不是文化自负，要在交流互鉴中坚定自信。既不能妄自菲薄，也不能盲目排外，要以开放胸怀吸收人类文明优秀成果，让中华文化在兼收并蓄中历久弥新。", "材料六：从《典籍里的中国》让古籍“活”起来，到国潮品牌把传统元素融入现代设计，从非遗工坊带动乡村就业，到中文热席卷全球，中华文化的创造力正在被重新激发。文化自信，从来不是抽象口号，它流淌在每个中国人的血脉里，绽放在每一次传统与现代的对话中，也必将凝聚起民族复兴的磅礴力量。"], "question": "请结合给定资料，围绕“文化自信”这一主题，自拟题目，写一篇文章。（50分）要求：观点明确，论证充分，条理清晰，语言流畅；1000~1200字。", "wordLimit": 1200, "scorePoints": [{"point": "标题切合文化自信主题", "synonyms": ["文化自信", "文化", "传统文化"], "score": 5, "aiOnly": true}, {"point": "立意准确，突出文化的根与魂", "synonyms": ["灵魂", "根与魂", "文化兴国运兴", "民族强"], "score": 12, "aiOnly": true}, {"point": "结构完整，分论点清晰", "synonyms": ["首先", "其次", "分论点", "层次"], "score": 10, "aiOnly": true}, {"point": "论证充分，例证丰富", "synonyms": ["故宫文创", "只此青绿", "举例", "事实论证"], "score": 13, "aiOnly": true}, {"point": "语言规范流畅", "synonyms": ["流畅", "规范", "文采"], "score": 10, "aiOnly": true}], "referenceAnswer": "以文化之自信 铸民族之精魂\n\n故宫文创让600岁的紫禁城“活”了起来，《只此青绿》舞出千里江山、一票难求。传统文化正以崭新姿态走进生活、赢得人心。文化是一个国家、一个民族的灵魂，文化兴国运兴，文化强民族强。\n文化自信，源于对文化根脉的深知。不了解何来自信。有人过洋节热闹、过传统节冷清，根子在于对传统文化的隔膜。要推动传统文化进课堂、进社区，让更多人知其然更知其所以然，在了解中生发认同，在认同中坚定自信。\n文化自信，成于创造性转化创新。自信不是抱残守缺。故宫文创把文物变成爆款产品，《只此青绿》让古画舞动起来，证明传统文化完全可以与现代生活相融。要善用科技赋能、创意激活，让收藏在博物馆里的文物、书写在古籍里的文字都活起来。\n文化自信，最终要落到生活日用。文化自信不是口号，而是融入日常的生活方式。穿汉服上街不再稀奇，茶道香道走进寻常人家，传统节日焕发新魅力——当文化成为生活的一部分，自信便有了最深厚的土壤。\n文以载道，以文化人。让我们在传承中坚守根脉，在创新中激发活力，在生活中涵养自信，以文化之自信，铸民族之精魂，为民族复兴凝聚深沉持久的力量。", "tips": "命题人提示：文化自信要答出“知—创—用”的递进逻辑，故宫文创、《只此青绿》是现成论据，可再补充身边文化现象。"}, {"id": "shl-42", "module": "shenlun", "category": "文章写作", "exam": "国考", "year": 2024, "source": "2024年国考副省级第五题（主题改写）", "title": "以“数字时代”为背景写文章", "material": ["材料一：数字技术深刻改变生产生活：智慧农业让种地有了“科技范”，远程医疗让山区群众在家门口看上专家号，直播电商让山货飞出大山。", "材料二：同时，数字鸿沟依然存在，一些老人不会用智能手机寸步难行；数据安全、算法滥用等问题时有发生。", "材料三：数字时代，既要拥抱变化，也要守住温度。", "材料四：某市推行“数字适老”改造，政务大厅保留人工窗口，医院设老年人绿色通道，社区开设手机课堂，帮助老人跨越数字鸿沟。", "材料五：也有专家指出，数字化不是目的，人民满意才是。技术再先进，也要给人留出选择的空间；效率再重要，也不能忽视少数群体的需求。数字时代的温度，体现在对每一个人的尊重与关怀。", "材料六：从健康码到智慧城市，从工业互联网到数字乡村，数字化浪潮席卷经济社会方方面面。有人欢呼技术带来的便利，也有人忧虑被算法“困住”。数字时代的发展与温度，本质是效率与公平、技术与人文的关系。唯有坚持以人为本，让技术向善，才能让数字化发展成果更多更公平惠及全体人民。"], "question": "请结合给定资料，围绕“数字时代的发展与温度”这一主题，自拟题目，写一篇文章。（50分）要求：观点明确，论证充分，条理清晰，语言流畅；1000~1200字。", "wordLimit": 1200, "scorePoints": [{"point": "标题切合主题", "synonyms": ["数字时代", "发展与温度", "数字技术"], "score": 5, "aiOnly": true}, {"point": "立意准确，兼顾发展与人文关怀", "synonyms": ["拥抱变化", "守住温度", "数字鸿沟", "以人为本"], "score": 12, "aiOnly": true}, {"point": "结构完整，分论点清晰", "synonyms": ["首先", "其次", "分论点", "层次"], "score": 10, "aiOnly": true}, {"point": "论证充分，例证丰富", "synonyms": ["智慧农业", "远程医疗", "直播电商", "举例"], "score": 13, "aiOnly": true}, {"point": "语言规范流畅", "synonyms": ["流畅", "规范", "文采"], "score": 10, "aiOnly": true}], "referenceAnswer": "数字时代：让发展提速 让温度常在\n\n智慧农业让种地有了“科技范”，远程医疗让山区群众看上专家号，直播电商让山货飞出大山——数字技术正深刻改变生产生活。然而，一些老人不会用智能手机寸步难行，数据安全隐忧时有发生。数字时代，既要拥抱变化提速发展，也要守住温度关怀人心。\n拥抱数字化，让发展插上翅膀。数字化是时代大势，谁错过数字化，谁就错过一个时代。要加快数字基建，推动数字技术与产业深度融合，让智慧农业、智能制造、数字政务释放红利，让数据多跑路、群众少跑腿。\n跨越数字鸿沟，不让一个人掉队。技术进步不能以牺牲弱势群体利益为代价。要为老年人保留线下渠道，开展智能设备培训，推行适老化改造，让技术更有温度。数字化的目的不是淘汰谁，而是服务每一个人。\n规范数字治理，守住安全底线。算法不能变成“算计”，大数据不能成为“杀熟”工具。要完善法律法规，压实平台责任，严惩数据滥用，让数字技术在法治轨道上健康发展。\n数字时代的大潮奔涌向前，发展是硬道理，温度是软实力。让我们既做数字化的推动者，也做人文关怀的守护者，让技术之光照亮生活，让数字时代既有速度、更有温度。", "tips": "命题人提示：主题是“发展与温度”的辩证关系，两个维度都要写；正面例证用材料三个场景，反面用数字鸿沟与算法问题。"}, {"id": "shl-43", "module": "shenlun", "category": "文章写作", "exam": "山东", "year": 2023, "source": "2023年山东省考第五题（主题改写）", "title": "以“工匠精神”为主题写文章", "material": ["材料一：大国工匠们几十年如一日打磨技艺：有人为火箭焊接“心脏”，误差不超过0.1毫米；有人一生只做一面镜子，磨出世界最大口径天文望远镜镜面。", "材料二：现实中，有人追求“短平快”，粗制滥造；有人耐不住寂寞，频繁跳槽。中国制造迈向中国智造，呼唤更多工匠。", "材料四：某职业院校开设工匠班，聘请大国工匠担任导师，学生毕业即被企业争抢。该校负责人说：“技能成才、技能报国，同样人生出彩。”", "材料五：也有企业建立首席技师制度，技能人才薪酬与管理层看齐，让一线工人有奔头。专家指出，弘扬工匠精神，既要有个人坚守，也要有制度支撑，让尊重劳动、崇尚技能成为社会风尚。", "材料六：从鲁班到庖丁，从样式雷到当代大国工匠，工匠精神一脉相承。它不仅是技艺的精进，更是心性的修炼——耐得住寂寞、守得住初心、经得起打磨。中国制造向中国创造转变，中国速度向中国质量跃升，呼唤千千万万劳动者以匠心铸就精品，用双手托举强国梦想。"], "question": "请结合给定资料，围绕“工匠精神”这一主题，自拟题目，写一篇文章。（50分）要求：观点明确，论证充分，条理清晰，语言流畅；1000~1200字。", "wordLimit": 1200, "scorePoints": [{"point": "标题切合工匠精神主题", "synonyms": ["工匠精神", "匠心", "精益求精"], "score": 5, "aiOnly": true}, {"point": "立意准确，突出专注与极致", "synonyms": ["专注", "极致", "精益求精", "耐得住寂寞"], "score": 12, "aiOnly": true}, {"point": "结构完整，分论点清晰", "synonyms": ["首先", "其次", "分论点", "层次"], "score": 10, "aiOnly": true}, {"point": "论证充分，正反结合", "synonyms": ["火箭焊接", "天文望远镜", "短平快", "举例"], "score": 13, "aiOnly": true}, {"point": "语言规范流畅", "synonyms": ["流畅", "规范", "文采"], "score": 10, "aiOnly": true}], "referenceAnswer": "以匠心致初心 以精工铸精品\n\n为火箭焊接“心脏”，误差不超过0.1毫米；一生磨一面镜，磨出世界最大口径天文望远镜镜面——大国工匠用毕生坚守诠释：所谓匠心，就是把一件事做到极致。\n工匠精神，是耐得住寂寞的专注。工匠之路没有捷径，唯有日复一日的打磨。反观有些人追求“短平快”，粗制滥造、频繁跳槽，看似聪明，实则难成大器。三百六十行，行行出状元，状元都从寂寞中走来。专注一事、深耕一域，方能水滴石穿。\n工匠精神，是差之毫厘不容的极致。0.1毫米的误差，在常人眼里微不足道，在工匠心中却是天堑。中国制造迈向中国智造，靠的正是这种对精度的执念。从高铁焊接到芯片制造，每一个精品背后，都是对标准的敬畏、对细节的较真。\n工匠精神，是传下去的薪火。一人匠心不如众匠成城。要完善技能人才培养体系，畅通技能人才成长通道，让技术工人有尊严、有奔头，让更多年轻人愿意学技术、争当工匠。\n匠心筑梦，精工致远。让我们以专注立身、以极致立业、以传承立人，让工匠精神融入中国制造的血脉，以匠心致初心，以精工铸精品，为高质量发展锻造坚实脊梁。", "tips": "命题人提示：工匠精神可从“专注—极致—传承”展开，材料两个大国工匠事例要善用，反面用“短平快”对照。"}, {"id": "shl-44", "module": "shenlun", "category": "文章写作", "exam": "江苏", "year": 2024, "source": "2024年江苏省考B类第五题（主题改写）", "title": "以“乡村振兴”为主题写文章", "material": ["材料一：某村引回能人办起服装厂，村民家门口就业；某村靠一片茶园富了全村；某村发展乡村旅游，节假日一房难求。", "材料二：也有村庄产业单一，一遇市场波动就伤筋动骨；有的村庄空心化严重，缺人、缺钱、缺技术。", "材料四：某县实施“雁归工程”，三年回引人才1200名，创办经营主体800余家，带动就业上万人。", "材料五：也有村庄通过“三变”改革，资源变资产、资金变股金、农民变股东，村集体经济从零起步发展到百万元。专家指出，乡村振兴要激活内生动力，让农民成为主角，让市场配置资源，政府做好引导和服务。", "材料六：从“千万工程”到脱贫攻坚，从人居环境整治到和美乡村建设，乡村大地正发生深刻变革。产业兴旺、生态宜居、乡风文明、治理有效、生活富裕，二十字方针描绘出乡村振兴的美好图景。蓝图已绘就，关键在落实，需要一代代人接续奋斗，把美好愿景一步步变成现实。"], "question": "请结合给定资料，围绕“乡村振兴”这一主题，自拟题目，写一篇文章。（50分）要求：观点明确，论证充分，条理清晰，语言流畅；1000~1200字。", "wordLimit": 1200, "scorePoints": [{"point": "标题切合乡村振兴主题", "synonyms": ["乡村振兴", "乡村", "振兴"], "score": 5, "aiOnly": true}, {"point": "立意准确，突出产业人才等要素", "synonyms": ["产业兴旺", "人才", "要素", "因地制宜"], "score": 12, "aiOnly": true}, {"point": "结构完整，分论点清晰", "synonyms": ["首先", "其次", "分论点", "层次"], "score": 10, "aiOnly": true}, {"point": "论证充分，例证丰富", "synonyms": ["服装厂", "茶园", "乡村旅游", "举例"], "score": 13, "aiOnly": true}, {"point": "语言规范流畅", "synonyms": ["流畅", "规范", "文采"], "score": 10, "aiOnly": true}], "referenceAnswer": "奏响乡村振兴的“交响曲”\n引回能人办厂，村民家门口就业；一片茶园富了全村；乡村旅游让农房变客房——一个个生动实践告诉我们：乡村振兴没有统一模板，但产业、人才、融合是共同的乐章。\n产业是乡村振兴的根基。无产业不富。产业单一，一遇市场波动就伤筋动骨；产业兴旺，乡村才有造血功能。要立足资源禀赋，宜农则农、宜游则游，发展特色产业，延长产业链条，让土特产变成金招牌。\n人才是乡村振兴的活水。乡村空心化，缺人更缺能人。要筑巢引凤，以政策回引能人返乡，以事业留住人才扎根；同时培育本土“田秀才”“土专家”，让愿意留在乡村的人留得安心，让愿意上山下乡的人更有信心。\n融合是乡村振兴的路径。单打独斗难成气候，融合发展天地宽广。推进一二三产融合，让农业接二连三；推动城乡融合，让城市的资金、技术、消费进村，让乡村的生态、文化、产品进城，在双向奔赴中激活全局。\n乡村振兴是一篇大文章，需要产业打底、人才执笔、融合着色。让我们因地制宜、久久为功，让农业成为有奔头的产业，让农民成为有吸引力的职业，让乡村成为安居乐业的美丽家园。", "tips": "命题人提示：乡村振兴要抓住产业、人才、融合三个关键，材料三个村庄事例对应不同路径，可提炼为因地制宜的论据。"}, {"id": "shl-45", "module": "shenlun", "category": "文章写作", "exam": "国考", "year": 2021, "source": "2021年国考副省级第五题（主题改写）", "title": "以“民生温度”为主题写文章", "material": ["材料一：某市把财政支出的七成以上投向民生：老旧小区加装电梯、普惠幼儿园扩容、社区食堂让老人吃上热乎饭。", "材料二：民生工作无小事，一枝一叶总关情。也有地方民生工程重建设轻管护，健身器材坏了没人修，惠民设施成了摆设。", "材料四：某市推行“民生实事项目人大代表票决制”，政府干什么的先问群众，项目由人大代表投票决定，办得好不好由群众评议。", "材料五：也有地方建立民生项目“回头看”制度，对建成项目跟踪问效，防止重建轻管。专家指出，民生温度来自制度保障，把群众满意作为第一标准，民生实事才能件件落到实处。", "材料六：从“幼有所育”到“老有所养”，从“病有所医”到“住有所居”，民生保障网越织越密。民生改善没有终点，只有连续不断的新起点。把人民放在心中最高位置，用心用情用力解决群众急难愁盼问题，一件事情接着一件事情办，一年接着一年干，民生温度必将转化为发展热度。"], "question": "请结合给定资料，围绕“民生温度”这一主题，自拟题目，写一篇文章。（50分）要求：观点明确，论证充分，条理清晰，语言流畅；1000~1200字。", "wordLimit": 1200, "scorePoints": [{"point": "标题切合民生主题", "synonyms": ["民生", "温度", "民生温度"], "score": 5, "aiOnly": true}, {"point": "立意准确，突出为民情怀", "synonyms": ["为民", "一枝一叶总关情", "群众利益", "以人为本"], "score": 12, "aiOnly": true}, {"point": "结构完整，分论点清晰", "synonyms": ["首先", "其次", "分论点", "层次"], "score": 10, "aiOnly": true}, {"point": "论证充分，正反结合", "synonyms": ["财政七成", "社区食堂", "重建设轻管护", "举例"], "score": 13, "aiOnly": true}, {"point": "语言规范流畅", "synonyms": ["流畅", "规范", "文采"], "score": 10, "aiOnly": true}], "referenceAnswer": "民生温度标注幸福刻度\n\n财政支出的七成以上投向民生，老旧小区加装电梯、普惠幼儿园扩容、社区食堂热气腾腾——一座城市的民生投入清单，就是百姓幸福的刻度表。民生无小事，一枝一叶总关情。\n民生温度，体现在真金白银的投入上。民生投入不是负担，而是最划算的投资。财政向民生倾斜，群众的后顾之忧少了，消费底气足了，发展内生动力也就强了。要把每一分民生资金花在刀刃上，让投入变成看得见、摸得着的幸福。\n民生温度，体现在急难愁盼的回应上。民生工作要雪中送炭，不能锦上添花。群众盼什么就干什么：上学难就扩普惠学位，养老难就建社区食堂，停车难就挖潜车位。把小事当大事办，把群众的“急难愁盼”当成头等大事，温度自然可感可及。\n民生温度，体现在建管并重的坚持上。有的地方重建设轻管护，健身器材坏了没人修，惠民设施成了摆设。民生工程不能一建了之，要建立长效管护机制，让好事办好、实事办实，经得起时间和群众检验。\n治国有常，利民为本。让我们以真金白银的投入、急难愁盼的回应、建管并重的坚持，持续增进民生福祉，让发展更有温度，让幸福更有质感。", "tips": "命题人提示：民生主题要答出“投入—回应—管护”三个层次，反面材料“重建设轻管护”是重要论据，不可遗漏。"}, {"id": "shl-46", "module": "shenlun", "category": "文章写作", "exam": "浙江", "year": 2023, "source": "2023年浙江省考第五题（主题改写）", "title": "以“青年担当”为主题写文章", "material": ["材料一：北斗团队平均年龄31岁，嫦娥团队平均年龄33岁，青春力量托举大国重器。", "材料二：抗疫一线，“90后”“00后”挺身而出；乡村振兴一线，大学生村官、返乡青年扎根泥土。", "材料三：青年一代有理想、有本领、有担当，国家就有前途，民族就有希望。", "材料四：某高校研究生支教团二十余年接力，一批批青年奔赴西部，用知识点亮山区孩子的梦想。", "材料五：也有青年在科研一线十年磨剑，攻克“卡脖子”技术；也有青年在乡村直播间里，把家乡好物卖向全国。专家指出，青年担当没有统一模板，把个人所长融入国家所需，在平凡岗位上发光发热，就是最好的担当。", "材料六：从“请党放心、强国有我”的青春誓言，到“清澈的爱、只为中国”的深情告白，新时代青年用行动证明：青春的模样有千万种，奋斗的底色是一样的。生逢盛世，肩负重任，广大青年当珍惜伟大时代，勇担时代使命，让青春在为祖国、为民族、为人民的不懈奋斗中绽放绚丽之花。"], "question": "请结合给定资料，围绕“青年担当”这一主题，自拟题目，写一篇文章。（50分）要求：观点明确，论证充分，条理清晰，语言流畅；1000~1200字。", "wordLimit": 1200, "scorePoints": [{"point": "标题切合青年担当主题", "synonyms": ["青年", "担当", "青春"], "score": 5, "aiOnly": true}, {"point": "立意准确，突出青年与国家命运相连", "synonyms": ["有理想有本领有担当", "国家前途", "民族希望", "使命"], "score": 12, "aiOnly": true}, {"point": "结构完整，分论点清晰", "synonyms": ["首先", "其次", "分论点", "层次"], "score": 10, "aiOnly": true}, {"point": "论证充分，例证丰富", "synonyms": ["北斗", "嫦娥", "抗疫", "返乡青年"], "score": 13, "aiOnly": true}, {"point": "语言规范流畅", "synonyms": ["流畅", "规范", "文采"], "score": 10, "aiOnly": true}], "referenceAnswer": "以青春之我 担时代之责\n\n北斗团队平均年龄31岁，嫦娥团队平均年龄33岁——托举大国重器的，正是一张张年轻的面孔。青年一代有理想、有本领、有担当，国家就有前途，民族就有希望。\n青年担当，要有仰望星空的理想。理想是青春的灯塔。从“清澈的爱只为中国”的赤诚，到“把论文写在祖国大地上”的志向，一代代青年把个人理想融入国家事业。新时代青年当立鸿鹄志，把小我融入大我，让青春在为国为民中闪光。\n青年担当，要有脚踏实地的本领。担当不能只靠一腔热血。北斗青年十年磨一剑，抗疫青年在专业岗位上各展所长。本领从何而来？从学习中来，从实践中来。青年当珍惜韶华、潜心学习，到基层一线经风雨、壮筋骨，练就担当作为的铁肩膀。\n青年担当，要有挺身而出的勇气。关键时刻站得出来，危难关头豁得出去。抗疫一线，“90后”“00后”逆行出征；乡村振兴一线，返乡青年扎根泥土。哪里有需要，哪里就有青年的身影，这就是担当的样子。\n青春由磨砺而出彩，人生因奋斗而升华。愿广大青年以理想定向、以本领立身、以担当践行，在时代的广阔天地中施展抱负，以青春之我，担时代之责，让青春之花绽放在祖国最需要的地方。", "tips": "命题人提示：青年担当可按“理想—本领—勇气”展开，材料中北斗、嫦娥、抗疫、返乡青年都是现成论据，注意例证要具体。"}];